/* =========================================================
   MUSIC — two original procedural themes, no audio files.
   The header music button cycles: BRAVE KNIGHTS -> LONELY PLACES -> OFF.
   Both themes are synthesized live with WebAudio and cross-faded.
========================================================= */

class MedievalMusicEngine {
  constructor() {
    this.ctx = null;
    this.masterGain = null;
    this.started = false;
    this.mode = 'off'; // 'off' | 'knight' | 'lonely'
    this.scheduledUntil = 0;
    this.timerId = null;
    this.stepIdx = 0;
    this.trackStartedAt = 0;
    this.activeDrones = [];

    // Two deliberately different pieces, both synthesized live with WebAudio.
    // KNIGHT: D Dorian — bold, open intervals and a rising cadence.
    this.knight = {
      name: 'The Banner Beyond the Gate',
      scale: [293.66, 329.63, 349.23, 392.0, 440.0, 493.88, 523.25, 587.33],
      melody: [0,2,4,5,7,5,4,2, 0,2,4,5,7,6,5,4, 2,4,5,7,5,4,2,0],
      durations: [0.30,0.30,0.30,0.30,0.60,0.30,0.30,0.60, 0.30,0.30,0.30,0.30,0.60,0.30,0.30,0.60, 0.30,0.30,0.30,0.30,0.60,0.30,0.30,0.90],
      drone: [146.83, 220.0],
      tempo: 1,
    };

    // LONELY: A minor-ish Aeolian colour — sparse, descending, unresolved.
    this.lonely = {
      name: 'Where the Road Forgets',
      scale: [220.00, 246.94, 261.63, 293.66, 329.63, 349.23, 392.00, 440.00],
      melody: [4,3,2,1, 0,1,2,3, 4,3,2,0, 1,0,6,4, 3,2,1,0],
      durations: [0.55,0.55,0.75,0.55, 0.90,0.55,0.55,0.75, 0.55,0.55,0.75,0.90, 0.55,0.55,0.75,0.90, 0.55,0.55,0.75,1.20],
      drone: [110.00, 164.81],
      tempo: 0.88,
    };
  }

  init() {
    if (this.started) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    this.started = true;
    this.ctx = new (window.AudioContext || window.webkitAudioContext)();
    this.masterGain = this.ctx.createGain();
    this.masterGain.gain.value = 0;
    this.masterGain.connect(this.ctx.destination);
    this.scheduledUntil = this.ctx.currentTime + 0.1;
    this.timerId = setInterval(() => this.scheduler(), 200);
  }

  currentTrack() {
    return this.mode === 'lonely' ? this.lonely : this.knight;
  }

  setMode(mode) {
    this.init();
    const next = mode === 'knight' || mode === 'lonely' ? mode : 'off';
    const now = this.ctx.currentTime;

    if (next === this.mode) return;

    // Fade the whole musical bed, stop any old drone voices, then restart
    // the new phrase from its opening so switching tracks feels intentional.
    this.masterGain.gain.cancelScheduledValues(now);
    this.masterGain.gain.setValueAtTime(this.masterGain.gain.value, now);
    this.masterGain.gain.linearRampToValueAtTime(0, now + 0.45);

    this.activeDrones.forEach(({ osc, gain }) => {
      try {
        gain.gain.cancelScheduledValues(now);
        gain.gain.setValueAtTime(Math.max(0.0001, gain.gain.value), now);
        gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.35);
        osc.stop(now + 0.4);
      } catch (e) {}
    });
    this.activeDrones = [];

    this.mode = next;
    this.stepIdx = 0;
    this.scheduledUntil = now + 0.5;
    this.trackStartedAt = now + 0.5;

    if (next !== 'off') {
      this.masterGain.gain.setValueAtTime(0, now + 0.5);
      this.masterGain.gain.linearRampToValueAtTime(0.82, now + 1.6);
    }
  }

  playDrone(track, time) {
    const ctx = this.ctx;
    track.drone.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      osc.type = i === 0 ? 'triangle' : 'sine';
      osc.frequency.value = freq;
      const gain = ctx.createGain();
      const amount = track === this.knight ? (i === 0 ? 0.075 : 0.045) : (i === 0 ? 0.045 : 0.028);
      gain.gain.setValueAtTime(0, time);
      gain.gain.linearRampToValueAtTime(amount, time + 0.8);
      osc.connect(gain).connect(this.masterGain);
      osc.start(time);
      osc.stop(time + 8.0);
      this.activeDrones.push({ osc, gain });
    });
  }

  playNote(freq, time, dur, track) {
    const ctx = this.ctx;
    const fundamental = ctx.createOscillator();
    const harmonic = ctx.createOscillator();
    const envelope = ctx.createGain();
    const harmonicGain = ctx.createGain();

    // Knight = bright flute/woodwind character; Lonely = softer bell-like voice.
    fundamental.type = track === this.knight ? 'triangle' : 'sine';
    fundamental.frequency.value = freq;
    harmonic.type = 'sine';
    harmonic.frequency.value = freq * (track === this.knight ? 2 : 3);
    harmonicGain.gain.value = track === this.knight ? 0.10 : 0.055;

    const vibrato = ctx.createOscillator();
    const vibratoGain = ctx.createGain();
    vibrato.frequency.value = track === this.knight ? 5.2 : 4.3;
    vibratoGain.gain.value = track === this.knight ? 2.2 : 1.2;
    vibrato.connect(vibratoGain);
    vibratoGain.connect(fundamental.frequency);
    vibratoGain.connect(harmonic.frequency);

    const peak = track === this.knight ? 0.13 : 0.095;
    envelope.gain.setValueAtTime(0, time);
    envelope.gain.linearRampToValueAtTime(peak, time + (track === this.knight ? 0.045 : 0.10));
    envelope.gain.setValueAtTime(peak, Math.max(time + 0.11, time + dur - (track === this.knight ? 0.12 : 0.22)));
    envelope.gain.exponentialRampToValueAtTime(0.001, time + dur);

    fundamental.connect(envelope);
    harmonic.connect(harmonicGain).connect(envelope);
    envelope.connect(this.masterGain);

    fundamental.start(time); fundamental.stop(time + dur + 0.05);
    harmonic.start(time); harmonic.stop(time + dur + 0.05);
    vibrato.start(time); vibrato.stop(time + dur + 0.05);
  }

  scheduler() {
    if (!this.ctx || this.mode === 'off') return;
    const track = this.currentTrack();
    while (this.scheduledUntil < this.ctx.currentTime + 2.2) {
      const i = this.stepIdx % track.melody.length;
      const degree = track.melody[i];
      const dur = track.durations[i] * track.tempo;
      const time = this.scheduledUntil;
      if (this.stepIdx % track.melody.length === 0) this.playDrone(track, time);
      this.playNote(track.scale[degree], time, dur * 0.90, track);
      this.scheduledUntil += dur;
      this.stepIdx++;
    }
  }

  // Three-state music cycle: heroic -> lonely -> off -> heroic.
  cycle() {
    if (this.mode === 'off') this.setMode('knight');
    else if (this.mode === 'knight') this.setMode('lonely');
    else this.setMode('off');
    return this.mode;
  }
}

const musicEngine = new MedievalMusicEngine();

/* =========================================================
   SFX — short, procedurally synthesized combat sound cues.
   Same philosophy as the music engine: no audio files, just
   oscillators/noise shaped with envelopes and filters. Runs on
   its own AudioContext (unlocked on first tap anywhere) so it
   works independent of the music toggle.
========================================================= */

class SFXEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuffer = null;
    this.enabled = true;
  }

  setEnabled(enabled) {
    this.enabled = enabled;
  }

  ensureCtx() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || window.webkitAudioContext)();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.5;
      this.master.connect(this.ctx.destination);
      const bufferSize = this.ctx.sampleRate * 0.6;
      const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
      this.noiseBuffer = buffer;
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
  }

  _noise() {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    return src;
  }

  // Sword clank — a noise transient (the "impact") plus two short
  // inharmonic metallic partials ringing out.
  clank() {
    if (!this.enabled) return;
    this.ensureCtx();
    const ctx = this.ctx;
    const t = ctx.currentTime;

    const noise = this._noise();
    const noiseFilter = ctx.createBiquadFilter();
    noiseFilter.type = 'bandpass';
    noiseFilter.frequency.value = 2200;
    noiseFilter.Q.value = 1.2;
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0.5, t);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
    noise.connect(noiseFilter).connect(noiseGain).connect(this.master);
    noise.start(t); noise.stop(t + 0.1);

    [1450, 2350].forEach((freq, i) => {
      const osc = ctx.createOscillator();
      osc.type = 'triangle';
      osc.frequency.value = freq;
      const gain = ctx.createGain();
      gain.gain.setValueAtTime(0.22 - i * 0.05, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.18 + i * 0.05);
      osc.connect(gain).connect(this.master);
      osc.start(t); osc.stop(t + 0.25);
    });
  }

  // Whoosh — bandpass-filtered noise sweeping quickly downward. Played on dodge.
  whoosh() {
    if (!this.enabled) return;
    this.ensureCtx();
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const noise = this._noise();
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.Q.value = 0.9;
    filter.frequency.setValueAtTime(2600, t);
    filter.frequency.exponentialRampToValueAtTime(300, t + 0.28);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.35, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
    noise.connect(filter).connect(gain).connect(this.master);
    noise.start(t); noise.stop(t + 0.32);
  }

  // Thud — low pitch-dropping sine plus a soft low-passed noise thump.
  // Played when an enemy's attack actually lands on the player.
  thud() {
    if (!this.enabled) return;
    this.ensureCtx();
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(160, t);
    osc.frequency.exponentialRampToValueAtTime(60, t + 0.15);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.4, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
    osc.connect(gain).connect(this.master);
    osc.start(t); osc.stop(t + 0.2);

    const noise = this._noise();
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 400;
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0.25, t);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
    noise.connect(filter).connect(noiseGain).connect(this.master);
    noise.start(t); noise.stop(t + 0.12);
  }

  // Crit ting — a bright rising ring layered on top of a strike.
  critTing() {
    if (!this.enabled) return;
    this.ensureCtx();
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(2200, t);
    osc.frequency.exponentialRampToValueAtTime(3400, t + 0.06);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.25, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.2);
    osc.connect(gain).connect(this.master);
    osc.start(t); osc.stop(t + 0.22);
  }

  // Defeat crunch — a low-passed noise burst sweeping down. Played when an enemy falls.
  defeatCrunch() {
    if (!this.enabled) return;
    this.ensureCtx();
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const noise = this._noise();
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(1800, t);
    filter.frequency.exponentialRampToValueAtTime(150, t + 0.35);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.4, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.38);
    noise.connect(filter).connect(gain).connect(this.master);
    noise.start(t); noise.stop(t + 0.4);
  }

  // Twang — a plucked, quickly pitch-dropping tone for thrown knives, the
  // handcannon, and the bow, so ranged hits feel distinct from melee clanks.
  twang() {
    if (!this.enabled) return;
    this.ensureCtx();
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(900, t);
    osc.frequency.exponentialRampToValueAtTime(300, t + 0.12);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.22, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.14);
    osc.connect(gain).connect(this.master);
    osc.start(t); osc.stop(t + 0.16);
  }

  // Block — a single bright short ring for a fully-blocked/deflected attack
  // (Stoneskin) or a dodge-adjacent parry moment.
  block() {
    if (!this.enabled) return;
    this.ensureCtx();
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.value = 1800;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.22, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
    osc.connect(gain).connect(this.master);
    osc.start(t); osc.stop(t + 0.17);
  }

  // Level up — a quick three-note ascending chime.
  levelUp() {
    if (!this.enabled) return;
    this.ensureCtx();
    const ctx = this.ctx;
    const t = ctx.currentTime;
    [523.25, 659.25, 783.99].forEach((freq, i) => {
      const start = t + i * 0.09;
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = freq;
      const gain = ctx.createGain();
      gain.gain.setValueAtTime(0, start);
      gain.gain.linearRampToValueAtTime(0.28, start + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, start + 0.25);
      osc.connect(gain).connect(this.master);
      osc.start(start); osc.stop(start + 0.28);
    });
  }
}

const sfxEngine = new SFXEngine();


