/* ---------------------------------------------------------
   THE EXPONENTIAL DESCENT

   The first 46 biomes remain fully authored. After them, four independent
   sixteen-part axes produce 65,536 deterministic realms per recursion.
   Recursion numbers make the chain unbounded without storing generated
   biome definitions in the save. The biome index is the seed: returning to
   a depth always reconstructs exactly the same name, colour, prose, enemies,
   Atlas gear and mastery nodes.
--------------------------------------------------------- */
const PROCEDURAL_BIOME_PREFIXES = ['Ashen','Bleeding','Brass','Candlelit','Crimson','Drowned','Echoing','Fevered','Glass','Hollow','Inverted','Last','Marrow','Pale','Shattered','Unremembered'];
const PROCEDURAL_BIOME_PLACES = ['Abbey','Archive','Bastion','Catacomb','Causeway','Citadel','Conservatory','Foundry','Gallery','Garden','Labyrinth','Observatory','Ossuary','Sanctum','Theatre','Vault'];
const PROCEDURAL_BIOME_DOMAINS = ['Borrowed Hours','Broken Names','Cold Fire','Endless Rain','Forgotten Gods','Glass Sleep','Hunger','Impossible Bells','Last Light','Living Ink','Mercy','Red Snow','Second Shadows','Silent Teeth','Stolen Faces','Unfinished Dreams'];
const PROCEDURAL_BIOME_EPITHETS = ['the Afterwake','the Black Noon','the Crooked Moon','the Drowned Hour','the Empty Feast','the Final Guest','the Glass Dawn','the Hidden Door','the Last Witness','the Long Return','the Missing King','the Ninth Echo','the Pale Star','the Red Memory','the Second Ending','the Unlit Crown'];
const PROCEDURAL_BIOME_STATES = ['breathes around every footstep','changes shape whenever it is named','has been waiting for precisely one visitor','is collapsing upward into an absent sky','keeps a careful inventory of the living','remembers futures that never happened','rings with footsteps from the next room','has locked every exit from the outside','grows a little larger whenever blood is spilled','is lit by a moon buried somewhere beneath it','repeats its final minute without reaching the end','has mistaken the dead for its permanent residents','is slowly teaching the walls to listen','contains a horizon that moves in the wrong direction','was abandoned by something too frightened to return','refuses to admit that it has already ended'];
const PROCEDURAL_BIOME_ACCENTS = ['#ff6b6b','#d98a5f','#e8c15a','#92d36e','#4ed1a8','#45b8d8','#668cff','#9c78e8','#d66bd4','#ef6fa7','#d8d2c4','#7d91a6','#b08b68','#7ec7c3','#c58bd6','#e07555'];
const PROCEDURAL_BIOME_GEAR = [
  ['Bell-Eater','Tollkeeper'],['Hour-Cleaver','Chronicle Warden'],['Name-Thief','Nameless'],['Rainspike','Storm-Buried'],
  ['Godshard','Votive'],['Dreamglass','Somnolent'],['Hunger-Tooth','Starved'],['Resonance Pike','Echo-Forged'],
  ['Lastlight Saber','Duskbound'],['Ink-Tide Trident','Scripted'],['Mercy-Ender','Absolution'],['Snowblood Axe','Redwinter'],
  ['Shadow-Twin','Afterimage'],['Ivory Fang','Silent-Maw'],['Face-Stealer','Masquerade'],['Unfinished Blade','Draftborn'],
];
// Keep procedural realm keys stable even if a later content update appends
// more authored biomes. New authored entries may occupy their explicit index,
// but every later generated index retains the same mixed-radix identity.
const AUTHORED_BIOME_ORIGIN_COUNT = 46;
const PROCEDURAL_BIOME_BLOCK_SIZE = 16 ** 4;
const PROCEDURAL_BIOME_CACHE = new Map();

function proceduralBiomeDigits(index) {
  let n = Math.max(0, index - AUTHORED_BIOME_ORIGIN_COUNT) % PROCEDURAL_BIOME_BLOCK_SIZE;
  return Array.from({ length:4 }, () => { const digit = n % 16; n = Math.floor(n / 16); return digit; });
}

function proceduralBiome(index) {
  if (PROCEDURAL_BIOME_CACHE.has(index)) return PROCEDURAL_BIOME_CACHE.get(index);
  const ordinal = Math.max(0, index - AUTHORED_BIOME_ORIGIN_COUNT);
  const d = proceduralBiomeDigits(index);
  const recursion = Math.floor(ordinal / PROCEDURAL_BIOME_BLOCK_SIZE) + 1;
  const recursionTag = recursion > 1 ? ` · Recursion ${recursion}` : '';
  const name = `The ${PROCEDURAL_BIOME_PREFIXES[d[0]]} ${PROCEDURAL_BIOME_PLACES[d[1]]} of ${PROCEDURAL_BIOME_DOMAINS[d[2]]}, ${PROCEDURAL_BIOME_EPITHETS[d[3]]}${recursionTag}`;
  const biome = {
    index,
    name,
    desc:`a ${PROCEDURAL_BIOME_PREFIXES[d[0]].toLowerCase()} ${PROCEDURAL_BIOME_PLACES[d[1]].toLowerCase()} where ${PROCEDURAL_BIOME_STATES[d[3]]}`,
    accent:PROCEDURAL_BIOME_ACCENTS[(d[0] + d[2] * 3 + d[3] * 5) % PROCEDURAL_BIOME_ACCENTS.length],
    procedural:true,
    recursion,
    ordinal:ordinal + 1,
    digits:d,
  };
  PROCEDURAL_BIOME_CACHE.set(index, biome);
  return biome;
}

function biomeAt(index) {
  return BIOMES[index] || proceduralBiome(index);
}

function biomeElementProfile(index) {
  const authored = AUTHORED_BIOME_ELEMENTS[index];
  if (authored) return { affinity:authored[0], weakness:authored[1], procedural:false };
  const biome = biomeAt(index);
  const identity = `${index}|${biome.name}|${biome.recursion || 0}|${(biome.digits || []).join(':')}`;
  const affinityIndex = hashStr(`affinity:${identity}`) % ELEMENT_KEYS.length;
  let weaknessIndex = hashStr(`weakness:${identity}`) % ELEMENT_KEYS.length;
  if (weaknessIndex === affinityIndex) weaknessIndex = (weaknessIndex + 1 + (hashStr(`counter:${identity}`) % (ELEMENT_KEYS.length - 1))) % ELEMENT_KEYS.length;
  return { affinity:ELEMENT_KEYS[affinityIndex], weakness:ELEMENT_KEYS[weaknessIndex], procedural:true };
}

function biomeElementSummary(index) {
  const profile = biomeElementProfile(index);
  const affinity = ELEMENTS[profile.affinity];
  const weakness = ELEMENTS[profile.weakness];
  return `${affinity.icon} ${affinity.name} affinity · ${weakness.icon} ${weakness.name} weakness`;
}

function currentBiome(depth) {
  // Absolute biome number. v1.45 used `% BIOMES.length` here, quietly
  // returning deep players to The Caverns after The Signal Wastes.
  return Math.max(0, Math.floor((Math.max(1, depth) - 1) / 10));
}

function biomeAccent(index) {
  return BIOME_ACCENT[index] || biomeAt(index).accent;
}

function biomeBackground(index) {
  const accent = biomeAccent(index);
  return BIOME_BACKGROUNDS[index] || `radial-gradient(ellipse 150% 100% at 50% -15%, ${accent}3d 0%, #14151b 60%)`;
}

function biomeLore(index) {
  if (BIOME_LORE[index]) return BIOME_LORE[index];
  const biome = biomeAt(index);
  return `Somewhere below, ${biome.name} ${PROCEDURAL_BIOME_STATES[biome.digits[3]]}. This is generated realm ${biome.ordinal.toLocaleString()} of the Exponential Descent, recursion ${biome.recursion.toLocaleString()}. The Atlas insists it existed before you arrived, although the ink is still wet.`;
}

function biomeGearTheme(index) {
  if (BIOME_GEAR_THEMES[index]) return BIOME_GEAR_THEMES[index];
  const biome = biomeAt(index);
  const gear = PROCEDURAL_BIOME_GEAR[(biome.digits[1] + biome.digits[2]) % PROCEDURAL_BIOME_GEAR.length];
  return { weapon:`${biome.name.replace(/^The /, '')} ${gear[0]}`, armor:`${gear[1]} Panoply` };
}

function proceduralBiomeIntroLines(index) {
  const biome = biomeAt(index);
  return [
    `${biome.name} assembles itself ahead of you, one unwilling corridor at a time.`,
    `The threshold closes. Behind it, ${biome.desc}.`,
    `Your Atlas grows a new page before your boots touch the floor of ${biome.name}.`,
    `Something in ${biome.name} has already counted you among its permanent features.`,
    `Recursion ${biome.recursion.toLocaleString()} begins to remember your footsteps.`,
  ];
}

function biomeIntroLines(index) {
  return BIOME_INTRO_LINES[index] || proceduralBiomeIntroLines(index);
}

function biomeTreasureLine(index) {
  return BIOME_TREASURE_LINES[index] || `A chest waits in ${biomeAt(index).name}, stamped with a forge key from a recursion that has not happened yet.`;
}

function biomeMerchantLine(index) {
  return BIOME_MERCHANT_LINES[index] || `The merchant has somehow reached ${biomeAt(index).name} first and refuses to explain the route.`;
}

function biomeCombatLines(index) {
  if (BIOME_COMBAT_LINES[index]) return BIOME_COMBAT_LINES[index];
  const place = biomeAt(index).name;
  return {
    solo:`A single local error detaches itself from ${place} and advances.`,
    pair:`Two incompatible versions of the same creature emerge from ${place}.`,
    group:`Three inhabitants of ${place} converge, each certain the others are intruders.`,
    boss:`The thing currently ruling ${place} has noticed the new page in your Atlas.`,
    bossGroup:`The ruler of ${place} arrives surrounded by lesser revisions of itself.`,
  };
}

