const CHAMPION_FIRST = ['Ash-Eyed','Bell-Eater','Black-Toothed','Candle-Crowned','Drowned','Glass-Blooded','Grave-Born','Hollow','Last','Moon-Bitten','Nameless','Pale','Red-Handed','Saintless','Salt-Wounded','Second','Starved','Unfinished'];
const CHAMPION_LAST = ['the Door-Collector','the Exitless','the First Mistake','the Kindly Knife','the Long Return','the Map-Eater','the Ninth Witness','the Room Behind You','the Small Catastrophe','the Tax of Bones','the Unburied','the Wrong Heir','Who Counts Your Steps','Who Outlived Tomorrow','Without a Shadow','Without Permission'];

function enemyMutationFor(template, biomeIndex, depth, rarity='common') {
  const seed=hashStr(`${template?.id||template?.name}|${biomeIndex}|${depth}|mutation`);
  const threshold=rarity==='legendary'?100:rarity==='rare'?68:38;
  return seed%100<threshold?ENEMY_MUTATIONS[Math.floor(seed/101)%ENEMY_MUTATIONS.length]:null;
}

function championIdentityFor(template, biomeIndex, depth, rarity='common') {
  const seed=hashStr(`${template?.id||template?.name}|${biomeIndex}|${depth}|champion`);
  const champion=rarity==='legendary'||(rarity==='rare'?seed%6===0:seed%23===0);
  if(!champion)return null;
  const first=CHAMPION_FIRST[Math.floor(seed/23)%CHAMPION_FIRST.length];
  const last=CHAMPION_LAST[Math.floor(seed/419)%CHAMPION_LAST.length];
  return {seed,title:`${first}, ${last}`,icon:'♛',desc:`A named survivor of ${biomeAt(biomeIndex).name}. The dungeon has begun using it as punctuation.`};
}

