const FACTION_ADJECTIVES = ['Ashen','Bellbound','Black','Brass','Candle','Drowned','Glass','Gilded','Hollow','Last','Marrow','Pale','Red','Salt','Second','Silent','Starved','Unfinished'];
const FACTION_ORDERS = ['Accord','Choir','Court','Covenant','Guild','Host','Keepers','Parliament','Pilgrims','Republic','Synod','Union','Wardens','Witnesses'];
const FACTION_DOCTRINES = ['believe the dungeon is a sleeping god','tax every safe road','protect the native food web from outsiders','collect names before their owners die','trade memories as legal tender','hunt anything the Atlas cannot classify','build shrines at failed exits','consider every weapon a voting member','feed their dead to the local weather','intend to civilise the next recursion'];
const FACTION_BOONS = [
  {key:'atkRate',icon:'⚔️',label:'+8% ATK in this biome',value:.08}, {key:'defRate',icon:'🛡️',label:'+8% DEF in this biome',value:.08},
  {key:'goldRate',icon:'🪙',label:'+15% enemy gold here',value:.15}, {key:'xpRate',icon:'✦',label:'+15% enemy XP here',value:.15},
  {key:'dodgeChance',icon:'💨',label:'+5% dodge here',value:.05}, {key:'killHealRate',icon:'❤️',label:'heal 3% max HP per kill here',value:.03},
];

function biomeWorldLaws(index) {
  const seed=`${index}|${biomeAt(index).name}|world-laws`;
  const first=hashStr(`${seed}:first`)%BIOME_WORLD_LAWS.length;
  let second=hashStr(`${seed}:second`)%BIOME_WORLD_LAWS.length;
  if(second===first)second=(second+1+hashStr(`${seed}:step`)%(BIOME_WORLD_LAWS.length-1))%BIOME_WORLD_LAWS.length;
  return [BIOME_WORLD_LAWS[first],BIOME_WORLD_LAWS[second]];
}

function biomeFactions(index) {
  const seed=`${index}|${biomeAt(index).name}|factions`;
  return [0,1].map(side=>{
    const local=`${seed}:${side}`;
    const adjective=FACTION_ADJECTIVES[hashStr(`${local}:adj`)%FACTION_ADJECTIVES.length];
    const order=FACTION_ORDERS[hashStr(`${local}:order`)%FACTION_ORDERS.length];
    const boon=FACTION_BOONS[hashStr(`${local}:boon`)%FACTION_BOONS.length];
    return {id:`faction_${index}_${hashStr(local).toString(36)}`,name:`The ${adjective} ${order}`,doctrine:FACTION_DOCTRINES[hashStr(`${local}:doctrine`)%FACTION_DOCTRINES.length],icon:side?'⚑':'⚐',boon};
  });
}

function enemyBehaviourFor(template, biomeIndex, legendary=false) {
  const offset=legendary?3:0;
  return ENEMY_BEHAVIOURS[(hashStr(`${template?.id||template?.name}|${biomeIndex}|behaviour`)+offset)%ENEMY_BEHAVIOURS.length];
}

function ecologyPick(list, seed, salt) {
  return list[hashStr(`${seed}:${salt}`) % list.length];
}

function biomeEcology(index) {
  const biome = biomeAt(index);
  const profile = biomeElementProfile(index);
  const native = ECOLOGY_BY_ELEMENT[profile.affinity];
  const counter = ECOLOGY_BY_ELEMENT[profile.weakness];
  const seed = `${index}|${biome.name}|${biome.recursion || 0}|ecology`;
  const ecology = {
    biomeIndex:index,
    seed:hashStr(seed),
    climate:ecologyPick(native.climates, seed, 'climate'),
    flora:ecologyPick(native.flora, seed, 'flora'),
    prey:ecologyPick(native.prey, seed, 'prey'),
    predator:ecologyPick(native.predators, seed, 'predator'),
    decomposer:ecologyPick(native.decomposers, seed, 'decomposer'),
    resource:ecologyPick(native.resources, seed, 'resource'),
    phenomenon:ecologyPick(native.phenomena, seed, 'phenomenon'),
    invasive:ecologyPick(counter.prey, seed, 'invasive'),
  };
  ecology.cycle = `${ecology.flora} feed ${ecology.prey}; ${ecology.predator} regulate the herds; ${ecology.decomposer} return the dead to beds of ${ecology.resource}.`;
  ecology.pressure = `${ecology.invasive} thrive wherever the biome's ${elementMeta(profile.weakness).name.toLowerCase()} weakness breaks through.`;
  ecology.summary = `${ecology.climate} · ${ecology.flora} · ${ecology.predator}`;
  return ecology;
}

function ecologyNicheForEnemy(template, biomeIndex, legendary = false) {
  if (legendary) return ECOLOGY_NICHES[ECOLOGY_NICHES.length - 1];
  const rarityBias = template?.rarity !== 'common' ? 2 : 0;
  const index = (hashStr(`${template?.id || template?.name}|${biomeIndex}|niche`) + rarityBias) % (ECOLOGY_NICHES.length - 1);
  return ECOLOGY_NICHES[index];
}

function applyBiomeEcologyToEnemy(enemy, template, depth, legendary = false) {
  const biomeIndex = currentBiome(depth);
  const ecology = biomeEcology(biomeIndex);
  const niche = ecologyNicheForEnemy(template, biomeIndex, legendary || enemy.rarity === 'legendary');
  const laws=biomeWorldLaws(biomeIndex);
  const lawMult=laws.reduce((out,law)=>({hp:out.hp*law.hp,atk:out.atk*law.atk,def:out.def*law.def,xp:out.xp*law.xp,gold:out.gold*law.gold}),{hp:1,atk:1,def:1,xp:1,gold:1});
  const behaviour=enemyBehaviourFor(template,biomeIndex,legendary||enemy.rarity==='legendary');
  const phenomenon=biomePhenomenon(biomeIndex);
  const mutation=enemyMutationFor(template,biomeIndex,depth,enemy.rarity);
  const champion=championIdentityFor(template,biomeIndex,depth,enemy.rarity);
  const strain=mutation||{hp:1,atk:1,def:1,xp:1,gold:1};
  const championMult=champion?1.22:1;
  const maxHp = Math.max(1, Math.round(enemy.maxHp * niche.hp * lawMult.hp * phenomenon.hp * (strain.hp||1) * championMult));
  return {
    ...enemy,
    name:champion?`${enemy.name} — ${champion.title}`:enemy.name,
    hp:maxHp,
    maxHp,
    atk:Math.max(1, Math.round(enemy.atk * niche.atk * lawMult.atk * phenomenon.atk * (strain.atk||1) * championMult)),
    def:Math.max(0, Math.round(enemy.def * niche.def * lawMult.def * phenomenon.def * (strain.def||1) * championMult)),
    xp:Math.max(1, Math.round(enemy.xp * niche.xp * lawMult.xp * phenomenon.xp * (strain.xp||1) * (champion?1.42:1))),
    gold:Math.max(0, Math.round(enemy.gold * niche.gold * lawMult.gold * phenomenon.gold * (strain.gold||1) * (champion?1.52:1) * (behaviour.id==='hoarder'?1.45:1))),
    biome:biomeIndex,
    ecologyNiche:niche.id,
    ecologyNicheName:niche.name,
    ecologyIcon:niche.icon,
    ecologyLore:`${niche.desc} Here it participates in a cycle where ${ecology.cycle.charAt(0).toLowerCase()}${ecology.cycle.slice(1)}`,
    behaviour:behaviour.id,
    behaviourName:behaviour.name,
    behaviourIcon:behaviour.icon,
    behaviourDesc:behaviour.desc,
    worldLawIds:laws.map(law=>law.id),
    phenomenonId:phenomenon.id,
    phenomenonName:phenomenon.name,
    mutation:mutation?.id||null,
    mutationName:mutation?.name||null,
    mutationIcon:mutation?.icon||null,
    mutationDesc:mutation?.desc||null,
    mutationElementResist:mutation?.elementResist||0,
    mutationReflect:mutation?.reflect||0,
    champion:!!champion,
    championTitle:champion?.title||null,
    championIcon:champion?.icon||null,
    championLore:champion?.desc||null,
    behaviourUsed:false,
  };
}

// Per-biome ambient theming — CSS only, no image assets, to match the game's
// existing emoji/CSS visual language. BIOME_ACCENT is the "true color" of
// each biome; BIOME_BACKGROUNDS derives a background gradient from it. Note:
// most of the screen is covered by opaque dc-panel surfaces (by design, for
// legibility), so the gradient itself is only visible in the header area,
