const TRANSCENDENT_RARITIES = {
  masterful:{ name:'Masterful', prefix:'Masterwork', mult:1.42, color:'#ff784f', icon:'✥', lore:'A mortal craft perfected so completely that the dungeon has begun copying it badly.' },
  godhood:{ name:'Godhood', prefix:'Godwrought', mult:2.10, color:'#fff1a8', icon:'☀', lore:'The object no longer behaves like equipment. It behaves like a small, wearable commandment.' },
};

function transcendFabledItem(base, rarity) {
  const meta = TRANSCENDENT_RARITIES[rarity];
  if (!base || !meta) return base;
  const out = { ...base, id:`${rarity}_${String(base.id).replace(/^fabled_/, '')}`, name:`${meta.prefix} ${base.name}`, rarity, transcendent:true, transcendentLore:meta.lore };
  for (const stat of ['atk','def','luck']) if (Number(out[stat]) > 0) out[stat] = Math.max(1, Math.round(out[stat] * meta.mult));
  if (out.type === 'weapon') out.damageMultiplier = rarity === 'godhood' ? 1.35 : 1.15;
  else if (ELEMENTAL_ARMOR_TYPES.has(out.type)) out.thornsRate = rarity === 'godhood' ? 0.25 : 0.10;
  else out.critChance = (out.critChance || 0) + (rarity === 'godhood' ? 12 : 5);
  return out;
}
