function hashStr(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) { h = (h * 31 + s.charCodeAt(i)) | 0; }
  return Math.abs(h);
}

const ELEMENTAL_AFFIX_CHANCE = { common:0, uncommon:0, rare:0.18, epic:0.30, legendary:0.45, mythic:0.60, fabled:0.75, masterful:0.92, godhood:1, iconic:0.85 };
const ELEMENTAL_AFFIX_POWER = { rare:0.10, epic:0.12, legendary:0.15, mythic:0.18, fabled:0.22, masterful:0.30, godhood:0.42, iconic:0.25 };
const ELEMENTAL_WEAPON_TYPES = new Set(['weapon']);
const ELEMENTAL_ARMOR_TYPES = new Set(['armor','chestpiece','greaves','footwear','headgear']);
const ELEMENTAL_ACCESSORY_TYPES = new Set(['ring','earring','bracelet','trinket','necklace']);

function elementalUnit(seed, salt) {
  if (seed === null || seed === undefined) return Math.random();
  return (hashStr(`${seed}:${salt}`) % 1_000_000) / 1_000_000;
}

function applyElementalAffix(item, seed = null, guaranteed = false) {
  if (!item || item.element || String(item.id || '').startsWith('no_') || item.id === 'fists' || item.id === 'rags') return item;
  const eligible = ELEMENTAL_WEAPON_TYPES.has(item.type) || ELEMENTAL_ARMOR_TYPES.has(item.type) || ELEMENTAL_ACCESSORY_TYPES.has(item.type);
  if (!eligible) return item;
  const chance = ELEMENTAL_AFFIX_CHANCE[item.rarity] || 0;
  if (!guaranteed && (chance <= 0 || elementalUnit(seed, 'affix') >= chance)) return item;
  const element = ELEMENT_KEYS[Math.floor(elementalUnit(seed, 'element') * ELEMENT_KEYS.length) % ELEMENT_KEYS.length];
  const meta = ELEMENTS[element];
  const power = ELEMENTAL_AFFIX_POWER[item.rarity] || 0.10;
  const out = {
    ...item,
    element,
    elementalAffix:true,
    elementalLore:`${meta.name} has taken root in this piece. Its effect keys off a biome's permanent elemental profile, including realms the Atlas has not generated yet.`,
    name:String(item.name || '').startsWith(`${meta.gear} `) ? item.name : `${meta.gear} ${item.name}`,
  };
  if (ELEMENTAL_WEAPON_TYPES.has(item.type)) out.elementalDamage = power;
  else if (ELEMENTAL_ARMOR_TYPES.has(item.type)) out.elementalWard = Number((power * 0.8).toFixed(3));
  else {
    out.elementalDamage = Number((power * 0.45).toFixed(3));
    out.elementalWard = Number((power * 0.35).toFixed(3));
  }
  return out;
}

function elementMeta(key) {
  return ELEMENTS[key] || ELEMENTS.arcane;
}

