function ProceduralEnemyIcon({ enemy, size = 64, idSalt = 'enemy', decorative = false, dead = false, motion = true, surfaceTexture = true, shellOnly = false }) {
  const spec = enemyVisualSpec(enemy);
  if (!spec) return null;
  const shapeSpec = shellOnly ? {...spec, eyes:0, aggression:0.4, guard:0.4, mutated:false, champion:false} : spec;
  const nativeElement = elementMeta(biomeElementProfile(spec.biomeIndex).affinity);
  const safeId = `enemy-${spec.seed}-${hashStr(String(idSalt))}`;
  const bodyId = `${safeId}-body`, auraId = `${safeId}-aura`, surfaceId = `${safeId}-surface`;
  const duration = `${2.6 + (spec.seed % 17) / 10}s`;
  const surfaceFrequency = spec.surface === 'fur' ? '0.085 0.16' : spec.surface === 'scales' ? '0.13 0.18' : spec.surface === 'chitin' ? '0.07 0.22' : spec.surface === 'carved' ? '0.045' : '0.025';
  const displacement = spec.surface === 'fur' ? 2.4 + spec.furLength * 0.45 : spec.surface === 'botanical' ? 1.6 : spec.surface === 'ectoplasm' ? 1.2 : 0.7;
  const surfaceScale = spec.surface === 'scales' || spec.surface === 'chitin' ? 7 : spec.surface === 'fur' ? 4.5 : spec.surface === 'carved' ? 6 : 3;
  const label = `${enemy.name}: procedural ${spec.archetype} from ${spec.biomeName}, ${spec.rarity}`;
  return <svg width={size} height={size} viewBox="0 0 96 96" role={decorative ? undefined : 'img'} aria-hidden={decorative ? 'true' : undefined} aria-label={decorative ? undefined : label}
    style={{display:'block',flex:'0 0 auto',overflow:'visible',opacity:dead?0.32:1,filter:`${dead?'grayscale(1) ':''}drop-shadow(0 0 ${Math.max(3,size/12)}px ${nativeElement.color}${spec.elite?'aa':'66'})`}}>
    {!decorative && <title>{label}</title>}
    <defs>
      <radialGradient id={bodyId} cx={spec.mirrored?'64%':'36%'} cy="28%" r="76%"><stop offset="0" stopColor={mixHex(spec.highlight,'#ffffff',0.22)}/><stop offset="0.27" stopColor={spec.highlight}/><stop offset="0.58" stopColor={spec.body}/><stop offset="1" stopColor={spec.shadow}/></radialGradient>
      <radialGradient id={auraId}><stop offset="0" stopColor={spec.rarityColor} stopOpacity={spec.legendary?0.5:0.28}/><stop offset="1" stopColor={spec.rarityColor} stopOpacity="0"/></radialGradient>
      {surfaceTexture && <filter id={surfaceId} x="-18%" y="-18%" width="136%" height="136%" colorInterpolationFilters="sRGB">
        <feTurbulence type={spec.surface === 'scales' ? 'turbulence' : 'fractalNoise'} baseFrequency={surfaceFrequency} numOctaves={spec.surface === 'fur' ? 3 : 2} seed={spec.seed % 997} result="surfaceNoise" />
        <feDisplacementMap in="SourceGraphic" in2="surfaceNoise" scale={displacement} xChannelSelector="R" yChannelSelector="G" result="shaped" />
        <feSpecularLighting in="surfaceNoise" surfaceScale={surfaceScale} specularConstant={spec.surface === 'ectoplasm' ? 0.75 : 0.42} specularExponent={spec.surface === 'chitin' ? 28 : spec.surface === 'fur' ? 8 : 16} lightingColor={spec.highlight} result="surfaceLight">
          <feDistantLight azimuth={210 + spec.seed % 55} elevation="52" />
        </feSpecularLighting>
        <feComposite in="surfaceLight" in2="SourceAlpha" operator="in" result="clippedLight" />
        <feBlend in="shaped" in2="clippedLight" mode={spec.surface === 'fur' ? 'soft-light' : 'screen'} />
      </filter>}
    </defs>
    {!shellOnly && spec.elite && <circle cx="48" cy="49" r={spec.legendary?45:41} fill={`url(#${auraId})`}><animate attributeName="opacity" values="0.55;1;0.55" dur={duration} repeatCount="indefinite" /></circle>}
    {!shellOnly && spec.legendary && <circle cx="48" cy="48" r="43" fill="none" stroke={spec.rarityColor} strokeWidth="1.8" strokeDasharray="5 5"><animateTransform attributeName="transform" type="rotate" from="0 48 48" to="360 48 48" dur="10s" repeatCount="indefinite" /></circle>}
    {!shellOnly && spec.mutated && <circle cx="48" cy="48" r="39" fill="none" stroke={spec.highlight} strokeWidth="1.2" strokeDasharray="2 6" opacity=".82"><animateTransform attributeName="transform" type="rotate" from="360 48 48" to="0 48 48" dur="7s" repeatCount="indefinite" /></circle>}
    <g transform={`translate(${48 - 48*spec.bulk} ${48 - 48*spec.bulk}) scale(${spec.bulk})${spec.mirrored?' translate(96 0) scale(-1 1)':''}`}>
      {motion && !dead ? <g><animateTransform attributeName="transform" type="translate" values="0 0;0 -2;0 0" dur={duration} repeatCount="indefinite"/>{surfaceTexture ? <g filter={`url(#${surfaceId})`}><EnemyBaseShape spec={shapeSpec} fill={`url(#${bodyId})`} stroke={spec.shadow}/></g> : <EnemyBaseShape spec={shapeSpec} fill={`url(#${bodyId})`} stroke={spec.shadow}/>}</g> : surfaceTexture ? <g filter={`url(#${surfaceId})`}><EnemyBaseShape spec={shapeSpec} fill={`url(#${bodyId})`} stroke={spec.shadow}/></g> : <EnemyBaseShape spec={shapeSpec} fill={`url(#${bodyId})`} stroke={spec.shadow}/>} 
      {!shellOnly && <EnemyRune spec={spec} x={48} y={52} color={spec.highlight}/>} 
      {!shellOnly && spec.guard > 0.48 && <g fill={spec.highlight} stroke={spec.shadow} strokeWidth="1.2">{[26,38,50,62].map((x,i)=><path key={x} d={`M${x} ${72-i%2*3} L${x+5} ${77-i%2*3} L${x} ${82-i%2*3} L${x-5} ${77-i%2*3} Z`} />)}</g>}
      {!shellOnly && spec.aggression > 0.62 && <g fill="#fb7185" stroke={spec.shadow} strokeWidth="1">{[18,32,64,78].map((x,i)=><path key={x} d={`M${x} ${18+i%2*55} L${x+(i<2?-7:7)} ${11+i%2*64} L${x+(i<2?3:-3)} ${27+i%2*44} Z`} />)}</g>}
    </g>
    {!shellOnly && spec.procedural && <g><text x="78" y="88" textAnchor="middle" fontSize="17" fontWeight="900" fill="#7ee8d9" stroke="#071a18" strokeWidth="0.7">∞</text><circle cx="78" cy="82" r="12" fill="none" stroke="#7ee8d9" strokeWidth="1" strokeDasharray="2 3" /></g>}
    {!shellOnly && spec.mutated && <text x="15" y="89" textAnchor="middle" fontSize="13">{spec.mutationIcon}</text>}
    {!shellOnly && !dead && <g opacity="0.9"><circle cx="48" cy="48" r="44" fill="none" stroke={nativeElement.color} strokeWidth="1" strokeDasharray="1 7"><animateTransform attributeName="transform" type="rotate" from="0 48 48" to="360 48 48" dur="14s" repeatCount="indefinite" /></circle><text x="13" y="17" textAnchor="middle" fontSize="11" fill={nativeElement.pale}>{nativeElement.icon}</text></g>}
    {!shellOnly && (spec.legendary||spec.champion) && <path d="M35 11 L40 20 L48 8 L56 20 L62 11 L59 27 L38 27 Z" fill={spec.champion?'#e8a23d':spec.rarityColor} stroke="#fff3b0" strokeWidth="1.2" />}
  </svg>;
}

