function earnedSkillPoints(player) {
  return Math.floor((player.maxDepthReached || 1) / 5) + (player.bonusSkillPoints || 0);
}

function spentSkillPoints(player) {
  const overcap = player.skillsOvercap || {};
  return (player.skillsUnlocked || []).length + Object.values(overcap).reduce((sum, n) => sum + (Number(n) || 0), 0);
}

