/* ---------------------------------------------------------
   REGIONAL MASTERY — a direct-Souls prestige tree (like the
   Atlas) giving each biome its own 3-step mastery track:
   +10% damage against that biome's enemies, then +5% gold from
   them, then +5% luck from their loot. Strictly sequential per
   biome (damage -> gold -> luck). v1.50 renders these as a paged,
   discovery-gated constellation that can expand without limit.
--------------------------------------------------------- */


/* ---------------------------------------------------------
   ABYSSAL ARCHIVE — Atlas expansion.
   Anomalies do NOT create a fifth collectible system. They are a rare
   endgame route into the existing Coins / Cards / Stamps / Figures
   collections, prioritising records the player has not yet discovered.
--------------------------------------------------------- */
const ABYSSAL_ARCHIVE_COST = 60;
const COLLECTIBLE_CATEGORIES = ['coins', 'cards', 'stamps', 'figures'];
const COLLECTIBLE_SET_SIZE = 50;

function collectiblePoolSize(player, category) {
  return COLLECTIBLE_SET_SIZE;
}

const ANOMALY_OPTIONS = [
  { id: 'blood_oath', icon: '🩸', name: 'Blood Oath', desc: '+35 ATK, but sacrifice 12% of your maximum HP.' },
  { id: 'gilded_echo', icon: '🪙', name: 'Gilded Echo', desc: 'Gain a huge purse of gold and +25 Luck.' },
  { id: 'iron_memory', icon: '🛡️', name: 'Iron Memory', desc: '+25 DEF, +50 max HP, and restore to full HP.' },
  { id: 'glass_fate', icon: '🪞', name: 'Glass Fate', desc: '+25% chance to completely evade an enemy attack.' },
  { id: 'starved_moon', icon: '🌘', name: 'Starved Moon', desc: '+60 ATK, but lose 10% of your current HP.' },
  { id: 'astral_memory', icon: '✨', name: 'Astral Memory', desc: 'Gain a massive burst of XP and 3 Chests.' },
  { id: 'second_heart', icon: '💗', name: 'Second Heart', desc: 'Restore to full HP, gain +30 max HP, and survive one fatal blow this run.' },
  { id: 'merchant_oath', icon: '💰', name: "Merchant's Oath", desc: 'Gain 600 gold and +15 Luck.' },
];

function missingCollectionRecords(player) {
  const missing = [];
  COLLECTIBLE_CATEGORIES.forEach(category => {
    const owned = player.collectibles?.[category] || [];
    for (let index = 0; index < collectiblePoolSize(player, category); index++) {
      if (!owned.includes(index)) missing.push({ category, index });
    }
  });
  return missing;
}

function generateAnomalyRoom(depth, player) {
  const shuffled = [...ANOMALY_OPTIONS].sort(() => Math.random() - 0.5).slice(0, 3);
  const missing = missingCollectionRecords(player).sort(() => Math.random() - 0.5);
  const allRecords = COLLECTIBLE_CATEGORIES.flatMap(category =>
    Array.from({ length: collectiblePoolSize(player, category) }, (_, index) => ({ category, index }))
  );
  const pool = missing.length ? missing : allRecords.sort(() => Math.random() - 0.5);

  return {
    type: 'anomaly',
    enemies: [],
    cleared: false,
    claimed: false,
    offers: shuffled.map((o, i) => ({ ...o, collectible: pool[i % pool.length] })),
    depth,
  };
}

const REGIONAL_MASTERY_UNLOCK_COST = 60;

const ELEMENTAL_MASTERY_COSTS = [15, 25, 40, 60, 90];
const ELEMENTAL_MASTERY_TREE = ELEMENT_KEYS.flatMap(element => {
  const meta = ELEMENTS[element];
  return ELEMENTAL_MASTERY_COSTS.map((cost, index) => ({
    id:`element_${element}_${index + 1}`,
    element,
    tier:index + 1,
    cost,
    icon:meta.icon,
    name:`${meta.name} Mastery ${['I','II','III','IV','V'][index]}`,
    desc:`+5% ${meta.name} weakness damage while matching elemental gear is equipped.`,
  }));
});

function elementalMasteryNodeById(nodeId) {
  return ELEMENTAL_MASTERY_TREE.find(node => node.id === nodeId) || null;
}

function regionalMasteryCost(biomeIndex) {
  // True exponential cost growth, intentionally gentle enough that the
  // authored map remains reachable while distant recursive nodes become
  // meaningful long-term prestige goals. The billion-Soul ceiling keeps
  // every node numerically valid even millions of biomes into recursion.
  return Math.min(1_000_000_000, Math.max(10, Math.round(10 * (1.055 ** Math.min(400, Math.max(0, biomeIndex))))));
}

function regionalMasteryNodesForBiome(biomeIndex) {
  const biome = biomeAt(biomeIndex);
  const cost = regionalMasteryCost(biomeIndex);
  return [
    { id:`regional_dmg_${biomeIndex}`, biomeIndex, kind:'dmg', order:0, icon:'⚔️', name:`${biome.name}: Predator's Edge`, desc:`+10% damage against ${biome.name} enemies.`, cost },
    { id:`regional_gold_${biomeIndex}`, biomeIndex, kind:'gold', order:1, icon:'🪙', name:`${biome.name}: Plunderer's Eye`, desc:`+5% gold from ${biome.name} enemies.`, cost },
    { id:`regional_luck_${biomeIndex}`, biomeIndex, kind:'luck', order:2, icon:'🍀', name:`${biome.name}: Fortune's Favor`, desc:`+5% luck from ${biome.name} enemy loot.`, cost },
  ];
}

function regionalMasteryNodeById(nodeId) {
  const match = /^regional_(dmg|gold|luck)_(\d+)$/.exec(nodeId || '');
  if (!match) return null;
  const biomeIndex = Number(match[2]);
  return regionalMasteryNodesForBiome(biomeIndex).find(node => node.kind === match[1]) || null;
}

// Retained for authored-world validation and old callers. Recursive nodes
// are resolved on demand by regionalMasteryNodeById instead of being stored.
const REGIONAL_MASTERY_TREE = BIOMES.flatMap((_, i) => regionalMasteryNodesForBiome(i));

// tier: 1, 2, or 3 (corresponding to the 30/60/90-visit thresholds)
function buildBiomeGear(biomeIndex, tier) {
  const theme = biomeGearTheme(biomeIndex);
  const roman = ['I', 'II', 'III'][tier - 1] || 'I';
  const biomeMult = 1 + biomeIndex * 0.15;
  const tierMult = 1 + (tier - 1) * 0.35;
  const atk = Math.round(18 * biomeMult * tierMult);
  const def = Math.round(12 * biomeMult * tierMult);
  return {
    weapon: { id: `atlas_${biomeIndex}_${tier}_wpn`, name: `${theme.weapon} ${roman}`, type: 'weapon', rarity: 'mythic', atk },
    armor:  { id: `atlas_${biomeIndex}_${tier}_arm`, name: `${theme.armor} ${roman}`,  type: 'armor',  rarity: 'mythic', def },
  };
}

function recordBiomeVisit(prestige, biomeIndex) {
  const biomeVisits = { ...(prestige.biomeVisits || {}) };
  biomeVisits[biomeIndex] = (biomeVisits[biomeIndex] || 0) + 1;
  return { ...prestige, biomeVisits };
}

// Returns log lines for any 30/60/90 thresholds newly crossed by this visit.
function atlasMilestoneLog(prevCount, newCount, biomeIndex) {
  const msgs = [];
  ATLAS_TIERS.forEach((t, i) => {
    if (prevCount < t && newCount >= t) {
      const gear = buildBiomeGear(biomeIndex, i + 1);
      msgs.push(`🗺️ Atlas Milestone: ${t}th visit to ${biomeAt(biomeIndex).name}! ${gear.weapon.name} and ${gear.armor.name} will await you at the start of your next descent.`);
    }
  });
  return msgs;
}

