// These are cumulative thresholds on legendary-tier boss/forge rolls:
// 2% Fabled, 0.3% Masterful and 0.03% Godhood once their nodes are owned.
function rollAscendantRarity(player, roll=Math.random()) {
  let cursor = 0;
  if (player?.godhoodForgeUnlocked) {
    if (roll < cursor + 0.0003) return 'godhood';
    cursor += 0.0003;
  }
  if (player?.masterfulForgeUnlocked) {
    if (roll < cursor + 0.003) return 'masterful';
    cursor += 0.003;
  }
  if (player?.fabledForgeUnlocked && roll < cursor + 0.02) return 'fabled';
  return 'legendary';
}

