const CABINET_PRESTIGE_NODE_BY_ID = Object.fromEntries(CABINET_PRESTIGE_NODES.map(node => [node.id, node]));

function tldrScore(item) {
  if (!item) return 0;
  return (Number(item.atk) || 0) + (Number(item.def) || 0) + (Number(item.luck) || 0);
}

function tldrWouldDisable(item, equipped) {
  return !!equipped && tldrScore(item) < tldrScore(equipped);
}

function equippedSlotsForMerchantItem(player, item) {
  if (!item || !player) return [];
  const slots = item.type === 'weapon' ? ['weapon','weapon2']
    : item.type === 'armor' ? ['armor']
    : item.type === 'ring' ? ['ring1','ring2','ring3','ring4','ring5']
    : item.type === 'earring' ? ['earring','earring2']
    : item.type === 'bracelet' ? ['bracelet1','bracelet2']
    : ['chestpiece','greaves','footwear','headgear','trinket','necklace'].includes(item.type) ? [item.type]
    : [];
  return slots.filter(slot => player[slot]).map(slot => ({ slot, item:player[slot] }));
}

function equippedItemsForMerchantItem(player, item) {
  return equippedSlotsForMerchantItem(player, item).map(entry => entry.item);
}

function merchantStrictUpgrade(item, player) {
  const equipped = equippedItemsForMerchantItem(player, item);
  if (!equipped.length || !ITEM_BAG_BY_TYPE[item?.type]) return false;
  const candidate = tldrScore(item);
  return candidate > Math.min(...equipped.map(tldrScore));
}

function tldrBiomeScore(item, biomeIndex) {
  const base = tldrScore(item);
  if (!item || !Number.isFinite(biomeIndex)) return base;
  const profile = biomeElementProfile(biomeIndex);
  const attackBonus = item.element === profile.weakness ? (Number(item.atk) || 0) * (Number(item.elementalDamage) || 0) : 0;
  const wardBonus = item.element === profile.affinity ? (Number(item.def) || 0) * (Number(item.elementalWard) || 0) : 0;
  return base + attackBonus + wardBonus;
}

function tldrUtilityScore(item, biomeIndex, smart = false) {
  const base = smart ? tldrBiomeScore(item, biomeIndex) : tldrScore(item);
  if (!item) return base;
  const atk = Number(item.atk) || 0;
  const def = Number(item.def) || 0;
  const crit = Math.max(0, Number(item.critChance) || 0) / 100;
  const dodge = Math.max(0, Number(item.dodge) || 0) / 100;
  const thorns = Math.max(0, Number(item.thornsRate) || 0);
  const leech = Math.max(0, Number(item.soulLeechChance) || 0) / 200;
  const damageLaw = Math.max(0, (Number(item.damageMultiplier) || 1) - 1);
  const utility = atk * (crit + leech + damageLaw) + def * (dodge + thorns);
  return base + utility;
}

function merchantUpgradeAnalysis(item, player, biomeIndex, smart = false, deep = false) {
  const equipped = equippedSlotsForMerchantItem(player, item);
  if (!equipped.length || !ITEM_BAG_BY_TYPE[item?.type]) return { delta:0, percent:0, candidateScore:0, currentScore:0, slot:null, current:null };
  const score = candidate => deep ? tldrUtilityScore(candidate, biomeIndex, smart) : smart ? tldrBiomeScore(candidate, biomeIndex) : tldrScore(candidate);
  const weakest = equipped.reduce((lowest, entry) => score(entry.item) < score(lowest.item) ? entry : lowest, equipped[0]);
  const candidateScore = score(item);
  const currentScore = score(weakest.item);
  const delta = candidateScore - currentScore;
  const percent = currentScore > 0 ? (delta / currentScore) * 100 : delta > 0 ? 100 : 0;
  return { delta, percent, candidateScore, currentScore, slot:weakest.slot, current:weakest.item };
}

function merchantUpgradeDelta(item, player, biomeIndex, smart = false, deep = false) {
  return merchantUpgradeAnalysis(item, player, biomeIndex, smart, deep).delta;
}

