function capstoneGateMet(node, prestige) {
  if (!node.gate) return true;
  if (node.gate === 'skills') return !!prestige.stamps5TreeUnlocked;
  if (node.gate === 'books') return !!prestige.cards9TreeUnlocked;
  if (node.gate === 'subcollections') return !!(prestige.figures11TreeUnlocked && prestige.stamps10TreeUnlocked && prestige.cards9TreeUnlocked && prestige.coins11TreeUnlocked);
  if (node.gate === 'mutations') return !!prestige.furtherMutationsUnlocked;
  if (node.gate === 'colours') return !!prestige.coins10TreeUnlocked;
  if (node.gate === 'ranged') return !!prestige.cards4TreeUnlocked;
  if (node.gate === 'bestiary') return !!(prestige.bestiaryUnlocked && prestige.cards5Unlocked);
  if (node.gate === 'atlas') return !!prestige.atlasUnlocked;
  if (node.gate === 'soulhunter') return (prestige.soulHunterUnlocked || []).length >= CARDS8_TREE.length;
  if (node.gate === 'soulwell') return !!prestige.soulwellUnlocked;
  return false;
}

function capstoneCanBuy(node, prestige) {
  const owned = prestige.capstoneUnlocked || [];
  return !owned.includes(node.id)
    && (!node.requires || owned.includes(node.requires))
    && capstoneGateMet(node, prestige)
    && prestige.souls >= node.cost;
}


