function getCollectibleFlavour(player, category, index) {
  const pool = COLLECTIBLE_FLAVOUR_TEMPLATES[category];
  const base = pool[index % pool.length];
  const origin = player?.collectibleOrigins?.[`${category}:${index}`];
  return `${base} ${collectionBiomeLore(category, index, origin)}`;
}

/* =========================================================
   HELPERS
========================================================= */

function pickRandom(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

function uid(base) {
  return `${base}_${Math.random().toString(36).slice(2, 9)}`;
}

function makeItemInstance(base) {
  const instance = { ...base, uid: uid(base.id) };
  return applyElementalAffix(instance);
}

// Used specifically for combat loot drops: the same named item found deeper
// in the dungeon hits/defends harder, mirroring enemy scaling (scaleEnemy).
function makeScaledItemInstance(base, depth) {
  const mult = 1 + Math.max(0, (depth - 1)) * 0.045;
  const scaled = { ...base, uid: uid(base.id) };
  if (scaled.atk) scaled.atk = Math.max(1, Math.round(scaled.atk * mult));
  if (scaled.def) scaled.def = Math.max(1, Math.round(scaled.def * mult));
  return applyElementalAffix(scaled);
}

/* ---------------------------------------------------------
   THE IMPOSSIBLE ARSENAL — ten independent sixteen-part axes
   produce 16^10 = 1,099,511,627,776 deterministic full names.
   A 40-bit forge key contains the complete name, so procedural
   weapons survive saves without storing or regenerating huge tables.
   Each also carries one of sixteen mechanical "weapon laws".
--------------------------------------------------------- */
const PROC_ORIGIN_PREFIXES = ['Ash','Black','Bleak','Blood','Bone','Brass','Candle','Cinder','Clock','Crown','Dawn','Dread','Dream','Frost','Grave','Hollow'];
const PROC_ORIGIN_SUFFIXES = ['fall','gate','haven','hold','march','mire','reach','rest','scar','spire','tide','vale','vault','wake','ward','weald'];
const PROC_MATERIAL_PREFIXES = ['Aether','Amber','Ash','Bone','Brass','Cinder','Cloud','Dragon','Dream','Dusk','Echo','Frost','Grave','Moon','Star','Void'];
const PROC_MATERIAL_SUFFIXES = ['alloy','bone','bronze','crystal','glass','iron','ivory','jade','obsidian','pearl','quartz','silver','steel','stone','thread','wood'];
const PROC_ADJECTIVES = ['Accursed','Ancient','Blasphemous','Clockwork','Crooked','Crowned','Devouring','Exiled','Gilded','Impossible','Laughing','Nameless','Recursive','Singing','Unfinished','Wrong'];
const PROC_FORMS = [
  { name:'Blade', emoji:'🗡️' }, { name:'Cleaver', emoji:'🔪' }, { name:'Dirk', emoji:'🗡️' }, { name:'Falchion', emoji:'⚔️' },
  { name:'Glaive', emoji:'🔱' }, { name:'Greatsword', emoji:'⚔️' }, { name:'Halberd', emoji:'🔱' }, { name:'Hatchet', emoji:'🪓' },
  { name:'Katana', emoji:'🗡️' }, { name:'Lance', emoji:'🔱' }, { name:'Maul', emoji:'🔨' }, { name:'Rapier', emoji:'🤺' },
  { name:'Saber', emoji:'⚔️' }, { name:'Scythe', emoji:'⚔️' }, { name:'Spear', emoji:'🔱' }, { name:'Warhammer', emoji:'🔨' },
];
const PROC_VIRTUES = ['Courage','Dawn','Defiance','Fortune','Grace','Hunger','Mercy','Memory','Patience','Rebellion','Silence','Spite','Starlight','Truth','Vengeance','Wonder'];
const PROC_CATASTROPHES = ['the Black Sun','the Broken Hour','the Candle Flood','the Crownless War','the Dead Moon','the Deepest Door','the Empty Choir','the Final Winter','the Glass Plague','the Hollow Sea','the Last King','the Nameless Fire','the Red Silence','the Second Ending','the Starless Road','Tomorrow'];
const PROC_TITLES = ["The King's Argument",'The Last Witness','The Quiet Heresy','The Door Opener','The Debt Collector','The Saint Eater','The Gentle Catastrophe','The Final Draft','The Unasked Question','The Long Way Down','The Honest Mistake','The Crown Refuser','The Grave Comedian','The Horizon Cutter','The Unfinished Answer','The Thing That Returned'];
const PROC_RUNES = ['Ⅰ','Ⅱ','Ⅲ','Ⅳ','Ⅴ','Ⅵ','Ⅶ','Ⅷ','Ⅸ','Ⅹ','Ⅺ','Ⅻ','ⅩⅢ','ⅩⅣ','ⅩⅤ','ⅩⅥ'];
const PROCEDURAL_NAME_AXES = [PROC_ORIGIN_PREFIXES, PROC_ORIGIN_SUFFIXES, PROC_MATERIAL_PREFIXES, PROC_MATERIAL_SUFFIXES, PROC_ADJECTIVES, PROC_FORMS, PROC_VIRTUES, PROC_CATASTROPHES, PROC_TITLES, PROC_RUNES];
const PROCEDURAL_NAME_COUNT = PROCEDURAL_NAME_AXES.reduce((total, axis) => total * axis.length, 1);

const PROCEDURAL_WEAPON_LAWS = [
  { id:'red_hunger', name:'Law of Red Hunger', desc:'Basic strikes heal 10% of damage dealt.', effect:{ procLifestealRate:0.10 } },
  { id:'no_armour', name:'Law of No Armour', desc:'Basic strikes have a 15% chance to ignore all defence.', effect:{ procIgnoreDefChance:15 } },
  { id:'twice_spoken', name:'Law of Twice-Spoken Steel', desc:'12% chance for a basic strike to echo for half damage.', effect:{ procEchoChance:12 } },
  { id:'shared_thunder', name:'Law of Shared Thunder', desc:'15% chance to arc 35% damage into another enemy.', effect:{ procCleaveChance:15 } },
  { id:'stolen_second', name:'Law of the Stolen Second', desc:'8% chance a basic strike prevents retaliation.', effect:{ procStasisChance:8 } },
  { id:'gilded_dead', name:'Law of the Gilded Dead', desc:'Enemies drop 25% more gold while this is equipped.', effect:{ procGoldBonus:0.25 } },
  { id:'hungry_margin', name:'Law of the Hungry Margin', desc:'Enemies grant 25% more XP while this is equipped.', effect:{ procXpBonus:0.25 } },
  { id:'giants_regret', name:"Law of the Giant's Regret", desc:'Deal 35% more basic-strike damage to bosses.', effect:{ procBossDamage:0.35 } },
  { id:'cornered_wolf', name:'Law of the Cornered Wolf', desc:'Deal 40% more basic-strike damage below half HP.', effect:{ procLowHealthDamage:0.40 } },
  { id:'small_ending', name:'Law of the Small Ending', desc:'A basic strike executes enemies left below 12% HP.', effect:{ procExecuteThreshold:0.12 } },
  { id:'warm_ashes', name:'Law of Warm Ashes', desc:'Each kill restores 8% of your maximum HP.', effect:{ procKillHealRate:0.08 } },
  { id:'returned_blow', name:'Law of the Returned Blow', desc:'15% extra chance to counterattack when struck.', effect:{ procCounterChance:0.15 } },
  { id:'soul_tax', name:'Law of the Soul Tax', desc:'+1% chance for a defeated enemy to drop a Soul.', effect:{ soulLeechChance:1 } },
  { id:'overclocked_heart', name:'Law of the Overclocked Heart', desc:'+12% critical-hit chance.', effect:{ critChance:12 } },
  { id:'dancing_edge', name:'Law of the Dancing Edge', desc:'+3% dodge chance while equipped.', effect:{ dodge:3 } },
  { id:'impossible_answer', name:'Law of the Impossible Answer', desc:'+25% weapon damage and +5 Luck.', effect:{ damageMultiplier:1.25, luck:5 } },
];

function proceduralNameDigits(forgeKey) {
  let remaining = Math.floor(Math.abs(Number(forgeKey) || 0)) % PROCEDURAL_NAME_COUNT;
  return PROCEDURAL_NAME_AXES.map(axis => {
    const digit = remaining % axis.length;
    remaining = Math.floor(remaining / axis.length);
    return digit;
  });
}

function proceduralWeaponName(forgeKey) {
  const d = proceduralNameDigits(forgeKey);
  const origin = `${PROC_ORIGIN_PREFIXES[d[0]]}${PROC_ORIGIN_SUFFIXES[d[1]]}`;
  const material = `${PROC_MATERIAL_PREFIXES[d[2]]}${PROC_MATERIAL_SUFFIXES[d[3]]}`;
  return `${origin} ${material} ${PROC_ADJECTIVES[d[4]]} ${PROC_FORMS[d[5]].name} of ${PROC_VIRTUES[d[6]]} Against ${PROC_CATASTROPHES[d[7]]}, ${PROC_TITLES[d[8]]} [${PROC_RUNES[d[9]]}]`;
}

function proceduralRoll(forgeKey, salt) {
  return (hashStr(`${forgeKey}:${salt}`) % 1000000) / 1000000;
}

function randomForgeKey() {
  return Math.floor(Math.random() * PROCEDURAL_NAME_COUNT);
}

function makeProceduralWeapon(depth, sourceRarity = 'rare', player = null, forcedForgeKey = null) {
  const forgeKey = forcedForgeKey === null ? randomForgeKey() : Math.floor(Math.abs(forcedForgeKey)) % PROCEDURAL_NAME_COUNT;
  const d = proceduralNameDigits(forgeKey);
  const rarityOrder = ['common','uncommon','rare','epic','legendary','mythic','fabled','masterful','godhood'];
  const sourceIndex = Math.max(1, rarityOrder.indexOf(sourceRarity));
  const rarityBump = proceduralRoll(forgeKey, 'rarity') > 0.72 ? 1 : 0;
  const maxRarity = player?.godhoodForgeUnlocked ? 8 : player?.masterfulForgeUnlocked ? 7 : player?.fabledForgeUnlocked ? 6 : 5;
  let rarity = rarityOrder[Math.min(maxRarity, sourceIndex + rarityBump)];
  if (sourceIndex >= 4) {
    const ascendantRoll = proceduralRoll(forgeKey, 'ascendant-rarity');
    const ascendant = rollAscendantRarity(player, ascendantRoll);
    if (rarityOrder.indexOf(ascendant) > rarityOrder.indexOf(rarity)) rarity = ascendant;
  }
  const baseAtk = { common:5, uncommon:8, rare:12, epic:18, legendary:26, mythic:32, fabled:40, masterful:52, godhood:72 }[rarity];
  const scale = 1 + Math.max(0, depth - 1) * 0.045;
  const law = PROCEDURAL_WEAPON_LAWS[hashStr(`${forgeKey}:law`) % PROCEDURAL_WEAPON_LAWS.length];
  const atk = Math.max(1, Math.round(baseAtk * scale * (0.9 + proceduralRoll(forgeKey, 'edge') * 0.25)));
  const def = proceduralRoll(forgeKey, 'guard') > 0.45 ? Math.max(1, Math.round(baseAtk * scale * (0.08 + proceduralRoll(forgeKey, 'balance') * 0.18))) : 0;
  const item = {
    id:`impossible_${forgeKey.toString(36)}`, uid:uid(`impossible_${forgeKey.toString(36)}`),
    name:proceduralWeaponName(forgeKey), type:'weapon', rarity, atk, ...(def ? { def } : {}),
    emoji:PROC_FORMS[d[5]].emoji, proceduralWeapon:true, forgeKey:String(forgeKey), procLaw:law.id,
    procLawName:law.name, procLawDesc:law.desc,
    forgeLore:`Forged under ${PROC_CATASTROPHES[d[7]]} from ${PROC_MATERIAL_PREFIXES[d[2]]}${PROC_MATERIAL_SUFFIXES[d[3]].toLowerCase()}; recovered in ${biomeAt(currentBiome(depth)).name}. No second weapon can inherit this exact 40-bit name-key.`,
    ...law.effect,
  };
  return applyElementalAffix(item, `impossible:${forgeKey}`);
}

// A compact, permanent trophy case for the last hundred impossible finds.
// The lifetime counter records encounters (including the astronomically
// unlikely event of seeing the same forge key twice); the archive itself
// de-duplicates keys so its display stays useful and save files stay small.
function recordImpossibleDiscovery(player, item, depth, source) {
  if (!item?.proceduralWeapon) return player;
  const forgeKey = String(item.forgeKey);
  const previous = player.impossibleArchive || [];
  const entry = {
    forgeKey,
    name: item.name,
    law: item.procLawName,
    rarity: item.rarity,
    depth: Math.max(1, depth || 1),
    biome: biomeAt(currentBiome(Math.max(1, depth || 1))).name,
    source,
    itemSnapshot: {
      name:item.name, rarity:item.rarity, type:item.type, atk:item.atk || 0, def:item.def || 0, luck:item.luck || 0,
      emoji:item.emoji, proceduralWeapon:true, forgeKey:String(item.forgeKey), procLaw:item.procLaw,
      procLawName:item.procLawName, procLawDesc:item.procLawDesc, forgeLore:item.forgeLore,
      element:item.element, elementalAffix:item.elementalAffix, elementalDamage:item.elementalDamage,
      elementalWard:item.elementalWard, elementalLore:item.elementalLore, transcendent:item.transcendent,
      transcendentLore:item.transcendentLore, damageMultiplier:item.damageMultiplier,
    },
  };
  return {
    ...player,
    impossibleFoundCount: (player.impossibleFoundCount || 0) + 1,
    impossibleArchive: [entry, ...previous.filter(found => String(found.forgeKey) !== forgeKey)].slice(0, 100),
  };
}

// Factory Sealed (Figures 8) — types eligible for the "Perfected" double-
// stats treatment. Deliberately excludes skillbooks and consumables; this
// is a gear-only prestige perk.
const FACTORY_SEALED_TYPES = new Set(['weapon', 'armor', 'ring', 'earring', 'bracelet', 'chestpiece', 'greaves', 'footwear', 'headgear', 'trinket', 'necklace']);

function applyFactorySealed(item, chance) {
  if (!item || !chance || item.rarity === 'iconic' || !FACTORY_SEALED_TYPES.has(item.type)) return item;
  if (Math.random() * 100 >= chance) return item;
  const perfected = { ...item, name: `Perfected ${item.name}`, factorySealed: true };
  if (perfected.atk) perfected.atk = perfected.atk * 2;
  if (perfected.def) perfected.def = perfected.def * 2;
  if (perfected.luck) perfected.luck = perfected.luck * 2;
  return perfected;
}

// Runs every generated loot item through the Factory Sealed roll in one
// pass, regardless of which tier/branch of loot generation produced it.
function applyFactorySealedToItems(items, chance) {
  if (!chance) return items;
  return items.map(it => applyFactorySealed(it, chance));
}

const COIN_MUTATION_TYPES = new Set(['weapon', 'armor', 'chestpiece', 'greaves', 'footwear', 'headgear', 'trinket', 'necklace', 'ring', 'earring', 'bracelet']);
const COIN_ARMOR_TYPES = new Set(['armor', 'chestpiece', 'greaves', 'footwear', 'headgear']);
const COIN_ACCESSORY_TYPES = new Set(['ring', 'earring', 'bracelet']);
const GEAR_ACCESSORY_TYPES = new Set(['ring', 'earring', 'bracelet', 'trinket', 'necklace']);
const ROYGBIV = [
  { name: 'Red', icon: '🔴' }, { name: 'Orange', icon: '🟠' }, { name: 'Yellow', icon: '🟡' },
  { name: 'Green', icon: '🟢' }, { name: 'Blue', icon: '🔵' }, { name: 'Indigo', icon: '🟣' }, { name: 'Violet', icon: '🟪' },
];

const RAINBOW_FILTERS = {
  Red: 'sepia(1) saturate(7) hue-rotate(320deg)',
  Orange: 'sepia(1) saturate(7) hue-rotate(340deg)',
  Yellow: 'sepia(1) saturate(8) hue-rotate(5deg)',
  Green: 'sepia(1) saturate(7) hue-rotate(65deg)',
  Blue: 'sepia(1) saturate(7) hue-rotate(175deg)',
  Indigo: 'sepia(1) saturate(7) hue-rotate(210deg)',
  Violet: 'sepia(1) saturate(7) hue-rotate(260deg)',
  White: 'grayscale(1) brightness(1.8)', Grey: 'grayscale(1) brightness(0.85)', Black: 'grayscale(1) brightness(0.35)',
  Burgundy: 'sepia(1) saturate(5) hue-rotate(300deg) brightness(0.65)', Brown: 'sepia(1) saturate(3) brightness(0.65)',
  Olive: 'sepia(1) saturate(4) hue-rotate(35deg) brightness(0.7)', Navy: 'sepia(1) saturate(5) hue-rotate(170deg) brightness(0.55)',
  Bronze: 'sepia(1) saturate(3) hue-rotate(345deg)', Silver: 'grayscale(1) brightness(1.35)', Gold: 'sepia(1) saturate(6) hue-rotate(355deg) brightness(1.2)', Platinum: 'grayscale(0.75) brightness(1.65)',
  Iridescent: 'saturate(2.4) hue-rotate(125deg) brightness(1.25)', Infrared: 'sepia(1) saturate(9) hue-rotate(305deg) brightness(1.15)', Ultraviolet: 'sepia(1) saturate(8) hue-rotate(245deg) brightness(1.05)',
};

const DEVOID_COLOURS = ['White', 'Grey', 'Black'];
const TROUBLED_COLOURS = ['Burgundy', 'Brown', 'Olive', 'Navy'];
const REGAL_COLOURS = [
  { name: 'Bronze', sell: 1.25 }, { name: 'Silver', sell: 1.5 },
  { name: 'Gold', sell: 1.75 }, { name: 'Platinum', sell: 2 },
];
const UNSETTLING_COLOURS = ['Iridescent', 'Infrared', 'Ultraviolet'];

function doubleItemStats(item) {
  const out = { ...item };
  if (out.atk) out.atk *= 2;
  if (out.def) out.def *= 2;
  if (out.luck) out.luck *= 2;
  return out;
}

function scalePositiveItemStats(item, mult) {
  const out = { ...item };
  ['atk', 'def', 'luck'].forEach(k => {
    if (Number(out[k]) > 0) out[k] = Math.max(1, Math.round(out[k] * mult));
  });
  return out;
}

function addItemColour(item, colour) {
  const previous = Array.isArray(item.rainbowColors)
    ? item.rainbowColors
    : (item.rainbowColor ? [item.rainbowColor] : []);
  const colors = previous.includes(colour) ? previous : [...previous, colour];
  return { ...item, rainbowColors: colors, rainbowColor: colour, rainbowIcon: colors.length > 1 ? '🌈' : '🎨' };
}

function rebuildMutationName(item) {
  let base = String(item.name || '').replace(/^((Dirty|Toughened|Sharpened|Enchanted|Envenomed|Ghostly|Cursed|Overdrive|Thorned|Leech|Red|Orange|Yellow|Green|Blue|Indigo|Violet|White|Grey|Black|Burgundy|Brown|Olive|Navy|Bronze|Silver|Gold|Platinum|Iridescent|Infrared|Ultraviolet|Cleaned|Perfected)(\/\w+)*\s+)+/, '');
  const prefixes = [];
  if (item.dirty) prefixes.push('Dirty');
  if (item.cleaned) prefixes.push('Cleaned');
  const colours = Array.isArray(item.rainbowColors) ? item.rainbowColors : (item.rainbowColor ? [item.rainbowColor] : []);
  if (colours.length) prefixes.push(colours.join('/'));
  if (item.factorySealed) prefixes.push('Perfected');
  if (item.sharpened) prefixes.push('Sharpened');
  if (item.toughened) prefixes.push('Toughened');
  if (item.enchanted) prefixes.push('Enchanted');
  if (item.envenomed) prefixes.push('Envenomed');
  if (item.ghostly) prefixes.push('Ghostly');
  if (item.cursedMutation) prefixes.push('Cursed');
  if (item.overdrive) prefixes.push('Overdrive');
  if (item.thorned) prefixes.push('Thorned');
  if (item.leech) prefixes.push('Leech');
  return `${prefixes.join(' ')}${prefixes.length ? ' ' : ''}${base}`;
}

function applyCursedRing(item) {
  const out = { ...item, cursedMutation: true };
  const stats = ['atk', 'def', 'luck'].filter(k => Number(out[k]) !== 0 && Number.isFinite(out[k]));
  if (stats.length >= 2) {
    const primary = pickRandom(stats);
    const other = stats.find(k => k !== primary) || stats[0];
    out[primary] = Math.max(1, Math.round(out[primary] * 3));
    out[other] = Math.max(1, Math.round(out[other] * 0.5));
  } else if (stats.length === 1) {
    const primary = stats[0];
    out[primary] = Math.max(1, Math.round(out[primary] * 2));
    const negative = primary === 'atk' ? 'def' : 'atk';
    out[negative] = -Math.max(1, Math.round(Math.abs(out[primary]) * 0.25));
  } else {
    out.atk = 1;
    out.def = -1;
  }
  out.name = rebuildMutationName(out);
  return out;
}

function applyCoinMutations(item, player) {
  if (!item || !COIN_MUTATION_TYPES.has(item.type)) return item;
  const tier = Number(player?.perfectedFindsTier || 0);
  const further = !!player?.furtherMutationsUnlocked;
  const advanced = !!(player?.freakyFunUnlocked || player?.devoidColourUnlocked || player?.furtherColoursUnlocked || player?.regalityUnlocked || player?.virtualInsanityUnlocked || player?.multiColourGearBoost || player?.complexityGearBoost);
  if (!tier && !further && !advanced) return item;
  let out = { ...item };
  const notes = [];

  // Each Perfected Finds tier independently unlocks exactly one of the five
  // original mutation rolls. The rolls themselves remain independent, so
  // stacked mutations are still possible.
  if (item.rarity !== 'iconic' && tier >= 1 && out.type === 'weapon' && Math.random() < 0.01) {
    out.dirty = true;
    notes.push('dirty');
  }
  if (item.rarity !== 'iconic' && tier >= 2 && COIN_ARMOR_TYPES.has(out.type) && Math.random() < 0.01) {
    out.toughened = true;
    out = doubleItemStats(out);
    notes.push('toughened');
  }
  if (item.rarity !== 'iconic' && tier >= 3 && out.type === 'weapon' && Math.random() < 0.01) {
    out.sharpened = true;
    out = doubleItemStats(out);
    notes.push('sharpened');
  }
  if (item.rarity !== 'iconic' && tier >= 4 && COIN_ACCESSORY_TYPES.has(out.type) && Math.random() < 0.01) {
    out.enchanted = true;
    out = doubleItemStats(out);
    notes.push('enchanted');
  }
  if (item.rarity !== 'iconic' && tier >= 5 && Math.random() < 0.01) {
    const colour = pickRandom(ROYGBIV);
    out = addItemColour(out, colour.name);
    out.rainbowIcon = colour.icon;
    out = doubleItemStats(out);
    notes.push(colour.name.toLowerCase());
  }

  // Further Mutations — three additional independent 1% rolls.
  if (item.rarity !== 'iconic' && further && out.type === 'weapon' && Math.random() < 0.01) {
    out.envenomed = true;
    out.damageMultiplier = (out.damageMultiplier || 1) * 1.2;
    notes.push('envenomed');
  }
  if (item.rarity !== 'iconic' && further && COIN_ARMOR_TYPES.has(out.type) && Math.random() < 0.01) {
    out.ghostly = true;
    out.dodge = (out.dodge || 0) + 1;
    notes.push('ghostly');
  }
  if (item.rarity !== 'iconic' && further && out.type === 'ring' && Math.random() < 0.01) {
    out = applyCursedRing(out);
    notes.push('cursed');
  }

  // Further Freaky Fun — independent from the earlier coin mutations, so a
  // piece can genuinely become something ridiculous when the one-percent
  // rolls collide.
  if (player?.freakyFunUnlocked && out.type === 'weapon' && Math.random() < 0.01) {
    out.overdrive = true;
    out.critChance = (out.critChance || 0) + 10;
    notes.push('overdrive');
  }
  if (player?.freakyFunUnlocked && COIN_ARMOR_TYPES.has(out.type) && Math.random() < 0.01) {
    out.thorned = true;
    out.thornsRate = (out.thornsRate || 0) + 0.25;
    notes.push('thorned');
  }
  if (player?.freakyFunUnlocked && GEAR_ACCESSORY_TYPES.has(out.type) && Math.random() < 0.01) {
    out.leech = true;
    out.soulLeechChance = (out.soulLeechChance || 0) + 1;
    notes.push('leech');
  }

  if (player?.devoidColourUnlocked && (out.type === 'weapon' || GEAR_ACCESSORY_TYPES.has(out.type)) && Math.random() < 0.01) {
    const colour = pickRandom(DEVOID_COLOURS);
    out = doubleItemStats(addItemColour(out, colour));
    notes.push(colour.toLowerCase());
  }
  if (player?.furtherColoursUnlocked && Math.random() < 0.01) {
    const colour = pickRandom(TROUBLED_COLOURS);
    out = doubleItemStats(addItemColour(out, colour));
    notes.push(colour.toLowerCase());
  }
  if (player?.regalityUnlocked && Math.random() < 0.01) {
    const colour = pickRandom(REGAL_COLOURS);
    out = doubleItemStats(addItemColour(out, colour.name));
    out.sellMultiplier = (out.sellMultiplier || 1) * colour.sell;
    notes.push(colour.name.toLowerCase());
  }
  if (player?.virtualInsanityUnlocked && Math.random() < 0.01) {
    const colour = pickRandom(UNSETTLING_COLOURS);
    out = doubleItemStats(addItemColour(out, colour));
    if (colour === 'Iridescent') out.luck = (out.luck || 0) + 5;
    if (colour === 'Infrared') out.critChance = (out.critChance || 0) + 15;
    if (colour === 'Ultraviolet') out.soulLeechChance = (out.soulLeechChance || 0) + 2;
    notes.push(colour.toLowerCase());
  }

  const colours = Array.isArray(out.rainbowColors) ? out.rainbowColors : (out.rainbowColor ? [out.rainbowColor] : []);
  if (player?.multiColourGearBoost && colours.length > 1 && !out.multiColourBoosted) {
    out = scalePositiveItemStats(out, 1 + (colours.length - 1) * 0.5);
    out.multiColourBoosted = true;
    notes.push(`${colours.length}-colour`);
  }
  const positiveStats = ['atk', 'def', 'luck'].filter(k => Number(out[k]) > 0).length;
  if (player?.complexityGearBoost && (out.type === 'weapon' || GEAR_ACCESSORY_TYPES.has(out.type)) && positiveStats > 1 && !out.complexityBoosted) {
    out = scalePositiveItemStats(out, 1.5);
    out.complexityBoosted = true;
    notes.push('complexity');
  }

  if (notes.length) {
    out.coinMutations = [...new Set([...(out.coinMutations || []), ...notes])];
    out.name = rebuildMutationName(out);
  }
  return out;
}

function applyCoinMutationsToItems(items, player) {
  const active = player?.perfectedFindsTier > 0 || player?.furtherMutationsUnlocked || player?.freakyFunUnlocked
    || player?.devoidColourUnlocked || player?.furtherColoursUnlocked || player?.regalityUnlocked
    || player?.virtualInsanityUnlocked || player?.multiColourGearBoost || player?.complexityGearBoost;
  return active ? items.map(it => applyCoinMutations(it, player)) : items;
}

function rarityAfterUpgrade(rarity, player=null) {
  const order = ['common', 'uncommon', 'rare', 'epic', 'legendary', 'mythic', 'fabled', 'masterful', 'godhood'];
  const i = order.indexOf(rarity || 'common');
  const max = player?.godhoodForgeUnlocked ? 8 : player?.masterfulForgeUnlocked ? 7 : player?.fabledForgeUnlocked ? 6 : 5;
  return order[Math.min(max, Math.max(0, i + 1))];
}

function cleanDirtyWeapon(item, player=null) {
  if (!item?.dirty || item.type !== 'weapon') return item;
  const out = { ...item };
  delete out.dirty;
  const oldRarity = out.rarity || 'common';
  const newRarity = rarityAfterUpgrade(oldRarity, player);
  if (newRarity !== oldRarity) {
    out.rarity = newRarity;
    if (out.atk) out.atk = Math.max(out.atk + 1, Math.round(out.atk * 1.5));
    if (out.def) out.def = Math.max(out.def + 1, Math.round(out.def * 1.5));
    if (out.luck) out.luck = Math.max(out.luck + 1, Math.round(out.luck * 1.5));
    const elementalPower = ELEMENTAL_AFFIX_POWER[newRarity] || 0;
    if (out.elementalDamage) out.elementalDamage = Math.max(out.elementalDamage, elementalPower);
    if (out.elementalWard) out.elementalWard = Math.max(out.elementalWard, elementalPower);
    const transcendence = TRANSCENDENT_RARITIES[newRarity];
    if (transcendence) {
      out.transcendent = true;
      out.transcendentLore = transcendence.lore;
      out.damageMultiplier = (out.damageMultiplier || 1) * (newRarity === 'godhood' ? 1.35 : 1.15);
    }
  }
  out.cleaned = true;
  out.name = rebuildMutationName(out);
  return out;
}

function applyMerchantPerfected(item, chance) {
  if (!item || !chance || !FACTORY_SEALED_TYPES.has(item.type)) return item;
  return applyFactorySealed(item, chance);
}

function isCombatRoom(type) {
  return type === 'combat' || type === 'legendary';
}

const PROCEDURAL_ENEMY_COMMON = [
  ['Ashbound Pilgrim','🕯️'],['Bell-Skinned Wretch','🔔'],['Borrowed Scribe','📜'],['Candle Eater','🕯️'],
  ['Drowned Bailiff','⚓'],['Echo Hound','🐺'],['Glass Penitent','🪞'],['Hollow Gardener','🌿'],
  ['Ink-Struck Drifter','🖋️'],['Marrow Porter','🦴'],['Pale Surveyor','📐'],['Red-Snow Stalker','🐾'],
  ['Second Shadow','👤'],['Silent Chorister','🎼'],['Threadbare Witness','🧵'],['Unfinished Resident','✏️'],
];
const PROCEDURAL_ENEMY_RARE = [
  ['The Absent Cartographer','🗺️'],['The Bell That Walks','🔔'],['The Borrowed Saint','🕊️'],['The Curator of Teeth','🦷'],
  ['The Drowned Tomorrow','🌊'],['The Emperor of Dust','👑'],['The Final Revision','📕'],['The Glass Confessor','🪞'],
  ['The Hunger Between Rooms','🕳️'],['The Ink Sovereign','🖋️'],['The Keeper of Last Light','🏮'],['The Moon Beneath','🌑'],
  ['The Recursion Warden','♾️'],['The Red Archivist','📚'],['The Unnamed Horizon','🌅'],['The Visitor Before You','🚪'],
];
const PROCEDURAL_ENEMY_CACHE = new Map();

function proceduralEnemyTemplates(biomeIndex) {
  if (PROCEDURAL_ENEMY_CACHE.has(biomeIndex)) return PROCEDURAL_ENEMY_CACHE.get(biomeIndex);
  const biome = biomeAt(biomeIndex);
  const d = biome.digits;
  const commonVariance = [0, 1, -1, 2];
  const rareVariance = [0, 8, 4, 14];
  const templates = [];
  for (let slot = 0; slot < 4; slot++) {
    const [role, emoji] = PROCEDURAL_ENEMY_COMMON[(d[0] + d[2] * 3 + slot * 5) % 16];
    const variance = commonVariance[slot];
    const goldMin = Math.round(3 + biomeIndex * 1.6) + variance;
    templates.push({
      id:`recursive_${biomeIndex}_common_${slot}`,
      name:`${role} of ${PROCEDURAL_BIOME_DOMAINS[(d[2] + slot) % 16]}`,
      rarity:'common', weight:24,
      hp:Math.round(18 + biomeIndex * 6.4) + variance * 2,
      atk:Math.round(5 + biomeIndex * 2.35) + (variance % 2),
      def:Math.round(1 + biomeIndex * 1.18) + (variance > 0 ? 1 : 0),
      xpBase:Math.round(8.5 + biomeIndex * 2.7) + variance,
      goldMin, goldMax:goldMin + 13 + variance, emoji, biome:biomeIndex, proceduralEnemy:true,
    });
  }
  for (let slot = 0; slot < 4; slot++) {
    const [role, emoji] = PROCEDURAL_ENEMY_RARE[(d[1] + d[3] * 3 + slot * 5) % 16];
    const variance = rareVariance[slot];
    const goldMin = Math.round(25 + biomeIndex * 8.2) + variance;
    templates.push({
      id:`recursive_${biomeIndex}_rare_${slot}`,
      name:`${role}, Recursion ${biome.recursion}`,
      rarity:'rare', weight:1,
      hp:Math.round(65 + biomeIndex * 23) + variance,
      atk:Math.round(11 + biomeIndex * 3.5) + Math.floor(variance / 4),
      def:Math.round(5 + biomeIndex * 2.1) + Math.floor(variance / 5),
      xpBase:Math.round(55 + biomeIndex * 12.5) + variance,
      goldMin, goldMax:goldMin + 95 + variance, emoji, biome:biomeIndex, proceduralEnemy:true,
    });
  }
  PROCEDURAL_ENEMY_CACHE.set(biomeIndex, templates);
  return templates;
}

function enemyTemplateById(enemyId) {
  const authored = ENEMY_TYPES.find(enemy => enemy.id === enemyId);
  if (authored) return authored;
  const match = /^recursive_(\d+)_(?:common|rare)_\d+$/.exec(enemyId || '');
  if (!match) return null;
  return proceduralEnemyTemplates(Number(match[1])).find(enemy => enemy.id === enemyId) || null;
}

function pickEnemyTemplate(depth) {
  const biome = currentBiome(depth);
  const pool = biome < BIOMES.length ? ENEMY_TYPES.filter(e => e.biome === biome) : proceduralEnemyTemplates(biome);
  const total = pool.reduce((s, e) => s + e.weight, 0);
  let r = Math.random() * total;
  for (const e of pool) {
    if (r < e.weight) return e;
    r -= e.weight;
  }
  return pool[0];
}

function enemyPoolForDepth(depth) {
  const biome = currentBiome(depth);
  return biome < BIOMES.length ? ENEMY_TYPES.filter(enemy => enemy.biome === biome) : proceduralEnemyTemplates(biome);
}

// An encounter is a little ecosystem, not a photocopier. Weighted sampling is
// deliberately without replacement so a trio cannot be three copies of the
// same template (and therefore three copies of one named champion).
function pickUniqueEnemyTemplates(depth, count, random = Math.random) {
  const available = [...enemyPoolForDepth(depth)];
  const picked = [];
  while (available.length && picked.length < count) {
    const total = available.reduce((sum, enemy) => sum + Math.max(0, enemy.weight || 0), 0);
    let roll = random() * Math.max(1, total);
    let index = 0;
    for (; index < available.length - 1; index++) {
      roll -= Math.max(0, available[index].weight || 0);
      if (roll < 0) break;
    }
    picked.push(available.splice(index, 1)[0]);
  }
  return picked;
}

function scaleEnemy(t, depth) {
  const mult = 1 + (depth - 1) * 0.12;
  const goldBase = t.goldMin + Math.random() * (t.goldMax - t.goldMin);
  return applyBiomeEcologyToEnemy({
    id: uid(t.id),
    baseId: t.id,
    name: t.name,
    emoji: t.emoji,
    rarity: t.rarity,
    hp: Math.round(t.hp * mult),
    maxHp: Math.round(t.hp * mult),
    atk: Math.round(t.atk * mult),
    def: Math.round(t.def * mult),
    xp: Math.round(t.xpBase * mult),
    gold: Math.round(goldBase * mult),
    lootGranted: false,
    depth,
  }, t, depth, false);
}

function scaleLegendary(t, depth) {
  const mult = 1 + (depth - 1) * 0.05;
  const goldBase = t.goldMin + Math.random() * (t.goldMax - t.goldMin);
  return applyBiomeEcologyToEnemy({
    id: uid(t.id),
    baseId: t.id,
    name: t.name,
    emoji: t.emoji,
    rarity: 'legendary',
    hp: Math.round(t.hp * mult),
    maxHp: Math.round(t.hp * mult),
    atk: Math.round(t.atk * mult),
    def: Math.round(t.def * mult),
    xp: Math.round(t.xpBase * mult),
    gold: Math.round(goldBase * mult),
    lootGranted: false,
    depth,
  }, t, depth, true);
}

function repairDuplicateEncounter(room, depth) {
  if (!room || !isCombatRoom(room.type) || !Array.isArray(room.enemies) || room.enemies.length < 2) return room;
  const used = new Set();
  const pool = enemyPoolForDepth(depth);
  let changed = false;
  const enemies = room.enemies.map((enemy, slot) => {
    const identity = enemy.baseId || String(enemy.id || '').replace(/_[a-z0-9]+_[a-z0-9]+$/i, '');
    if (!used.has(identity)) {
      used.add(identity);
      return enemy;
    }
    const alternatives = pool.filter(template => !used.has(template.id));
    if (!alternatives.length) return enemy;
    changed = true;
    const template = alternatives[hashStr(`${depth}|${slot}|${identity}|encounter-repair`) % alternatives.length];
    used.add(template.id);
    const replacement = scaleEnemy(template, depth);
    // Retain the fight exactly where the player left it while replacing all
    // identity/ecology/champion/visual metadata derived from the duplicated
    // template. Runtime IDs remain unique, so targeting remains stable.
    const preserve = new Set(['id','hp','maxHp','atk','def','xp','gold','lootGranted','depth','formationId','formationIndex','formationRole','formationAtkMult','formationDefMult','formationHpMult']);
    const repaired = { ...enemy };
    Object.entries(replacement).forEach(([key, value]) => { if (!preserve.has(key)) repaired[key] = value; });
    repaired.behaviourUsed = false;
    return repaired;
  });
  return changed ? { ...room, enemies, encounterRepaired: true } : room;
}

function damageRoll(atk, def) {
  const base = Math.max(1, atk - def);
  const variance = base * (0.8 + Math.random() * 0.5);
  return Math.max(1, Math.round(variance));
}

function getCollectibleCount(player) {
  return Object.values(player.collectibles).reduce((s, a) => s + a.length, 0);
}

function getLuck(player) {
  const equippedLuck = equippedGearItems(player).reduce((sum, item) => sum + (Number(item?.luck) || 0), 0);
  return getCollectibleCount(player) + (player.bonusLuck || 0) + equippedLuck + activePetEffect(player, 'luck');
}

// 0 - 0.25, scales with luck (caps around 167 effective luck)
function luckBonus(player) {
  return Math.min(0.25, getLuck(player) * 0.0015);
}

const BESTIARY_THRESHOLDS_BASE = [20, 40, 60];
const BESTIARY_THRESHOLDS_EXTENDED = [20, 40, 60, 100, 150, 200];
const BESTIARY_THRESHOLDS_EXTENDED2 = [20, 40, 60, 100, 150, 200, 300, 400, 500];
const BESTIARY_THRESHOLDS_EXTENDED3 = [20, 40, 60, 100, 150, 200, 300, 400, 500, 700, 900, 1200];

function bestiaryTierFor(player, baseId) {
  if (!player.bestiaryUnlocked) return 0;
  const thresholds = player.cards5Unlocked ? BESTIARY_THRESHOLDS_EXTENDED3
    : player.cards3Unlocked ? BESTIARY_THRESHOLDS_EXTENDED2
    : player.cards2Unlocked ? BESTIARY_THRESHOLDS_EXTENDED : BESTIARY_THRESHOLDS_BASE;
  const kills = (player.kills && player.kills[baseId]) || 0;
  let tier = 0;
  thresholds.forEach(t => { if (kills >= t) tier += 1; });
  return tier; // 0-3 normally, 0-6 with Cards 2, 0-9 with Cards 3
}

function isBestiaryComplete(player, baseId) {
  if (!player.bestiaryUnlocked || !player.cards5Unlocked) return false;
  return ((player.kills && player.kills[baseId]) || 0) >= BESTIARY_THRESHOLDS_EXTENDED3[BESTIARY_THRESHOLDS_EXTENDED3.length - 1];
}

// Returns { atkMult, defMult, dodgeBonus } for fighting a specific enemy baseId.
function bestiaryBonusVs(player, baseId) {
  const tier = bestiaryTierFor(player, baseId);
  return {
    atkMult: 1 + tier * 0.02,
    defMult: 1 + tier * 0.02,
    dodgeBonus: tier * 2,
  };
}

function getCollectibleName(player, category, index) {
  return (player.collectibleNames && player.collectibleNames[category] && player.collectibleNames[category][index])
    || COLLECTIBLE_NAMES[category][index];
}

function rollCollectible(player) {
  const categories = Object.keys(COLLECTIBLE_META);
  const cat = pickRandom(categories);
  const owned = player.collectibles[cat] || [];
  const missing = [];
  for (let i = 0; i < collectiblePoolSize(player, cat); i++) if (!owned.includes(i)) missing.push(i);
  if (missing.length === 0) return null;
  return { category: cat, index: pickRandom(missing) };
}

// Equipment coverage is selected by family first, then by item. This prevents
// large weapon/armor tables from statistically burying smaller unlocked slots.
// The same source of truth feeds enemies, chests, merchants and collectors.
function unlockedGearFamilyPools(player, rarity) {
  const mods = player?.bodyMods || [];
  const headgear = (player?.heavilyArmedUnlocked || []).includes('headgear');
  const unlocked = key => key === 'weapon' || key === 'armor' || key === 'ring' || key === 'earring'
    || (key === 'chestpiece' && mods.includes('vest'))
    || (key === 'greaves' && mods.includes('pants'))
    || (key === 'footwear' && mods.includes('feet'))
    || (key === 'headgear' && headgear)
    || (key === 'trinket' && mods.includes('trinket'))
    || (key === 'necklace' && mods.includes('necklace'))
    || (key === 'bracelet' && mods.includes('wrists'));
  const fabledFamilies = [
    ['weapon', FABLED_WEAPONS], ['armor', FABLED_ARMORS], ['ring', FABLED_RINGS], ['earring', FABLED_EARRINGS],
    ['bracelet', FABLED_BRACELETS], ['chestpiece', FABLED_CHESTPIECES], ['greaves', FABLED_GREAVES],
    ['footwear', FABLED_FOOTWEAR], ['headgear', FABLED_HEADGEAR], ['trinket', FABLED_TRINKETS], ['necklace', FABLED_NECKLACES],
  ];
  const transcendFamilies = rarityName => fabledFamilies.map(([key, items]) => [key, items.map(item => transcendFabledItem(item, rarityName))]);
  const tables = {
    common: [
      ['weapon', COMMON_WEAPONS], ['armor', COMMON_ARMORS], ['ring', COMMON_RINGS], ['earring', COMMON_EARRINGS],
      ['bracelet', COMMON_BRACELETS], ['chestpiece', COMMON_CHESTPIECES], ['greaves', COMMON_GREAVES],
      ['footwear', COMMON_FOOTWEAR], ['headgear', COMMON_HEADGEAR], ['trinket', COMMON_TRINKETS], ['necklace', COMMON_NECKLACES],
    ],
    uncommon: [
      ['weapon', UNCOMMON_WEAPONS], ['armor', UNCOMMON_ARMORS], ['ring', UNCOMMON_RINGS], ['earring', UNCOMMON_EARRINGS],
      ['bracelet', UNCOMMON_BRACELETS], ['chestpiece', UNCOMMON_CHESTPIECES], ['greaves', UNCOMMON_GREAVES],
      ['footwear', UNCOMMON_FOOTWEAR], ['headgear', UNCOMMON_HEADGEAR], ['trinket', UNCOMMON_TRINKETS], ['necklace', UNCOMMON_NECKLACES],
    ],
    rare: [
      ['weapon', RARE_WEAPONS], ['armor', RARE_ARMORS], ['ring', RARE_RINGS], ['earring', RARE_EARRINGS],
      ['bracelet', RARE_BRACELETS], ['chestpiece', RARE_CHESTPIECES], ['greaves', RARE_GREAVES],
      ['footwear', RARE_FOOTWEAR], ['headgear', RARE_HEADGEAR], ['trinket', RARE_TRINKETS], ['necklace', RARE_NECKLACES],
    ],
    epic: [
      ['weapon', EPIC_WEAPONS], ['armor', EPIC_ARMORS], ['chestpiece', EPIC_CHESTPIECES], ['greaves', EPIC_GREAVES],
      ['footwear', EPIC_FOOTWEAR], ['headgear', EPIC_HEADGEAR],
    ],
    legendary: [
      ['weapon', LEGENDARY_WEAPONS], ['armor', LEGENDARY_ARMORS], ['chestpiece', LEGENDARY_CHESTPIECES], ['greaves', LEGENDARY_GREAVES],
      ['footwear', LEGENDARY_FOOTWEAR], ['headgear', LEGENDARY_HEADGEAR],
    ],
    fabled: fabledFamilies,
    masterful: transcendFamilies('masterful'),
    godhood: transcendFamilies('godhood'),
  };
  return (tables[rarity] || []).filter(([key, items]) => unlocked(key) && items.length).map(([key, items]) => ({ key, items }));
}

function pickBalancedGear(player, rarity, allowedFamilies = null) {
  const families = unlockedGearFamilyPools(player, rarity).filter(family => !allowedFamilies || allowedFamilies.includes(family.key));
  if (!families.length) return null;
  const family = pickRandom(families);
  return pickRandom(family.items);
}

function unlockedGearFlatPool(player, rarity) {
  return unlockedGearFamilyPools(player, rarity).flatMap(family => family.items);
}

const ITEM_BAG_BY_TYPE = {
  weapon: 'weaponsBag', armor: 'armorsBag', chestpiece: 'chestpiecesBag', greaves: 'greavesBag', footwear: 'footwearBag',
  headgear: 'headgearBag', trinket: 'trinketsBag', necklace: 'necklacesBag', ring: 'accessoriesBag', earring: 'accessoriesBag',
  bracelet: 'accessoriesBag', skillbook: 'skillbooksBag',
};

function raritySellPrice(rarity) {
  return ({ common:12, uncommon:25, rare:50, epic:110, legendary:250, mythic:400, iconic:600, fabled:800, masterful:1800, godhood:5000 })[rarity] || 12;
}

function stashInventoryItem(player, rawItem, instantiate = false) {
  const bagKey = ITEM_BAG_BY_TYPE[rawItem?.type];
  if (!bagKey) return player;
  const item = instantiate ? makeItemInstance(rawItem) : rawItem;
  return { ...player, [bagKey]: [...(player[bagKey] || []), item] };
}

function rollLoot(enemy, player) {
  const enemyBiome = currentBiome(enemy.depth);
  const regionalLuckPct = ((player.regionalLuckBonus && player.regionalLuckBonus[enemyBiome]) || 0) / 100;
  const lb = luckBonus(player) + regionalLuckPct;
  let gold = enemy.gold, potions = 0, greaterPotions = 0, items = [], chest = false, keyItem = null, throwables = 0, bullets = 0, arrows = 0;
  const hasHandcannon = player.keyItems.includes('handcannon');
  const hasBow = player.keyItems.includes('bow');

  if (enemy.rarity === 'legendary') {
    const headlineRarity = rollAscendantRarity(player, Math.random());
    items.push(makeScaledItemInstance(pickBalancedGear(player, headlineRarity), enemy.depth));
    items.push(makeScaledItemInstance(pickBalancedGear(player, 'epic'), enemy.depth));
    if (Math.random() < ICONIC_DROP_CHANCE) items.push(makeItemInstance(buildIconicDrop(enemy, player)));
    gold += 100;
    greaterPotions += 2;
    potions += 2;
    const notOwned = RELIC_DROP_POOL.filter(k => !player.keyItems.includes(k.id));
    if (notOwned.length > 0) keyItem = pickRandom(notOwned).id;
  } else if (enemy.rarity === 'common') {
    // Every common-tier gear roll has a smaller, luck-scaling chance to
    // upgrade to an uncommon item instead — a nice surprise without
    // touching the base drop rates.
    const uncommonUpgradeChance = 0.15 + lb * 0.4;
    if (Math.random() < 0.25 + lb * 0.3) {
      const rarity = Math.random() < uncommonUpgradeChance ? 'uncommon' : 'common';
      items.push(makeScaledItemInstance(pickBalancedGear(player, rarity, ['weapon']), enemy.depth));
    }
    if (Math.random() < 0.2 + lb * 0.3) {
      const rarity = Math.random() < uncommonUpgradeChance ? 'uncommon' : 'common';
      items.push(makeScaledItemInstance(pickBalancedGear(player, rarity, ['armor', 'chestpiece', 'greaves', 'footwear', 'headgear']), enemy.depth));
    }
    if (Math.random() < 0.15 + lb * 0.3) {
      const rarity = Math.random() < uncommonUpgradeChance ? 'uncommon' : 'common';
      items.push(makeScaledItemInstance(pickBalancedGear(player, rarity, ['ring', 'earring', 'bracelet', 'trinket', 'necklace']), enemy.depth));
    }
    // Family coverage roll: every ordinary enemy has another modest chance to
    // reveal any currently unlocked equipment family without pool-size bias.
    if (Math.random() < 0.08 + lb * 0.16) {
      const rarity = Math.random() < uncommonUpgradeChance ? 'uncommon' : 'common';
      items.push(makeScaledItemInstance(pickBalancedGear(player, rarity), enemy.depth));
    }
    if (Math.random() < 0.05 + lb * 0.15) items.push(makeItemInstance(pickRandom(COMMON_SKILLBOOKS)));
    if (Math.random() < 0.3 + lb * 0.3) potions += 1;
    if (Math.random() < 0.12 + lb * 0.2) throwables += 1 + Math.floor(Math.random() * 3);
    if (hasHandcannon && Math.random() < 0.15 + lb * 0.2) bullets += 1 + Math.floor(Math.random() * 3);
    if (hasBow && Math.random() < 0.15 + lb * 0.2) arrows += 1 + Math.floor(Math.random() * 3);
  } else {
    // Rare foes guarantee one family-balanced rare item. Every unlocked family
    // has an equal shot before its individual item table is consulted.
    items.push(makeScaledItemInstance(pickBalancedGear(player, 'rare'), enemy.depth));
    if (Math.random() < 0.15 + lb * 0.5) items.push(makeScaledItemInstance(pickBalancedGear(player, 'epic'), enemy.depth));
    // Magical runes (rare skill books) are now a separate, rarer 5% drop.
    if (Math.random() < 0.05 + lb * 0.15) items.push(makeItemInstance(pickRandom(RARE_SKILLBOOKS)));
    if (Math.random() < ICONIC_DROP_CHANCE) items.push(makeItemInstance(buildIconicDrop(enemy, player)));
    if (Math.random() < 0.5) greaterPotions += 1;
    if (Math.random() < 0.35) potions += 1;
    gold += 10;
    if (Math.random() < 0.04 + lb * 0.2) chest = true;
    if (hasHandcannon && Math.random() < 0.4) bullets += 2 + Math.floor(Math.random() * 4);
    if (hasBow && Math.random() < 0.4) arrows += 2 + Math.floor(Math.random() * 4);
    if (Math.random() < 0.1) {
      const notOwned = RELIC_DROP_POOL.filter(k => !player.keyItems.includes(k.id));
      if (notOwned.length > 0) keyItem = pickRandom(notOwned).id;
    }
  }

  // The Impossible Arsenal is always alive. Ordinary enemies only rarely
  // punch through to it; bosses and legendary encounters tear wider holes.
  const impossibleChance = enemy.rarity === 'legendary' ? 0.20
    : enemy.rarity === 'rare' ? 0.05 + lb * 0.08
    : 0.003 + lb * 0.02;
  if (Math.random() < impossibleChance) {
    const sourceRarity = enemy.rarity === 'legendary' ? 'legendary' : enemy.rarity === 'rare' ? 'rare' : 'uncommon';
    items.push(makeProceduralWeapon(enemy.depth, sourceRarity, player));
  }

  // Double Pagination (Figures 7) — chance a found skill book duplicates itself.
  let paginationProc = false;
  if (player.doublePaginationChance) {
    items.filter(it => it.type === 'skillbook').forEach(b => {
      if (Math.random() * 100 < player.doublePaginationChance) {
        items.push({ ...b, uid: uid(b.id) });
        paginationProc = true;
      }
    });
  }

  items = applyFactorySealedToItems(items, player.factorySealedChance);
  items = applyCoinMutationsToItems(items, player);
  return { gold, potions, greaterPotions, items, chest, keyItem, throwables, bullets, arrows, paginationProc };
}

function generateInventoryChestLoot(depth, player) {
  const rarityRoll = Math.random();
  const rarity = rarityRoll < .03 ? 'legendary' : rarityRoll < .25 ? 'epic' : 'rare';
  const primaryBase = pickBalancedGear(player, rarity);
  const items = primaryBase ? [makeScaledItemInstance(primaryBase, depth)] : [];
  if (Math.random() < .28) {
    const secondBase = pickBalancedGear(player, Math.random() < .18 ? 'epic' : 'rare');
    if (secondBase) items.push(makeScaledItemInstance(secondBase, depth));
  }
  if (Math.random() < .20) {
    const bookPool = depth >= 30 && Math.random() < .45 ? RARE_SKILLBOOKS : COMMON_SKILLBOOKS;
    items.push(makeItemInstance(pickRandom(bookPool)));
  }
  return {
    gold: Math.round((35 + depth * 2.5 + Math.random() * 45) * (1 + (player.wealthLootBonus || 0))),
    potions: Math.random() < .35 ? 1 : 0,
    greaterPotions: Math.random() < .18 ? 1 : 0,
    items: applyCoinMutationsToItems(applyFactorySealedToItems(items, player.factorySealedChance), player),
  };
}

function recycleLearnedSpellBooks(stock, player) {
  if (!player?.bookRecyclingUnlocked) return stock;
  const learned = new Set(player.abilities || []);
  const remaining = RARE_SKILLBOOKS.filter(book => !learned.has(book.ability));
  let replacementIndex = 0;
  return stock.map(item => {
    if (item.type !== 'skillbook' || !item.ability || !learned.has(item.ability)) return item;
    const replacement = remaining.length
      ? remaining[replacementIndex++ % remaining.length]
      : COMMON_SKILLBOOKS[replacementIndex++ % COMMON_SKILLBOOKS.length];
    return { ...replacement, price:item.price, uid:uid(replacement.id), recycledFrom:item.id };
  });
}

function generateMerchantStock(depth, player) {
  const scale = 1 + depth * 0.04;
  const ledgerDiscount = (player && player.keyItems && player.keyItems.includes('merchant_ledger')) ? 0.85 : 1;

  const bmUnlocked = (player && player.betterMerchantUnlocked) || [];
  let bmDiscount = 1, extraSlots = 0, moreSkillbooks = false;
  bmUnlocked.forEach(nodeId => {
    const node = BETTER_MERCHANT_TREE.find(n => n.id === nodeId);
    if (!node) return;
    if (node.effect.discount) bmDiscount -= node.effect.discount;
    if (node.effect.extraSlots) extraSlots += node.effect.extraSlots;
    if (node.effect.moreSkillbooks) moreSkillbooks = true;
  });
  const discount = Math.max(0.5, ledgerDiscount * bmDiscount);

  const commonSkillbookPool = COMMON_SKILLBOOKS.map(it => ({ ...it, price: Math.round(15 * scale * discount) }));
  const rareSkillbookPool = RARE_SKILLBOOKS.map(it => ({ ...it, price: Math.round(95 * scale * discount) }));
  const commonPool = [
    ...unlockedGearFlatPool(player, 'common'), ...commonSkillbookPool,
  ].map(it => ({ ...it, price: Math.round(15 * scale * discount) }));
  const uncommonPool = [
    ...unlockedGearFlatPool(player, 'uncommon'),
  ].map(it => ({ ...it, price: Math.round(35 * scale * discount) }));
  const rarePool = [
    ...unlockedGearFlatPool(player, 'rare'), ...rareSkillbookPool,
  ].map(it => ({ ...it, price: Math.round(95 * scale * discount) }));
  const epicPool = [
    ...unlockedGearFlatPool(player, 'epic'),
  ].map(it => ({ ...it, price: Math.round(220 * scale * discount) }));
  const legendaryPool = [
    ...unlockedGearFlatPool(player, 'legendary'),
  ].map(it => ({ ...it, price: Math.round(650 * scale * discount) }));
  const fabledPool = [
    ...unlockedGearFlatPool(player, 'fabled'),
  ].map(it => ({ ...it, price: Math.round(1250 * scale * discount) }));
  const masterfulPool = [
    ...unlockedGearFlatPool(player, 'masterful'),
  ].map(it => ({ ...it, price: Math.round(2600 * scale * discount) }));
  const godhoodPool = [
    ...unlockedGearFlatPool(player, 'godhood'),
  ].map(it => ({ ...it, price: Math.round(7000 * scale * discount) }));

  // Merchant stock quality rises with depth — beginner gear phases out entirely
  // by depth 30, and a legendary occasionally shows up once you're deep enough
  // to actually afford one.
  let commonReps, uncommonReps, rareReps, epicReps, legendaryReps;
  if (depth < 12) { commonReps = 3; uncommonReps = 1; rareReps = 1; epicReps = 1; legendaryReps = 0; }
  else if (depth < 30) { commonReps = 1; uncommonReps = 2; rareReps = 2; epicReps = 1; legendaryReps = 0; }
  else if (depth < 55) { commonReps = 0; uncommonReps = 1; rareReps = 2; epicReps = 2; legendaryReps = 0; }
  else { commonReps = 0; uncommonReps = 0; rareReps = 1; epicReps = 2; legendaryReps = 1; }

  const weighted = moreSkillbooks
    ? [
        ...Array(commonReps).fill(commonSkillbookPool).flat(),
        ...Array(uncommonReps).fill(uncommonPool).flat(),
        ...Array(rareReps + 1).fill(rareSkillbookPool).flat(),
        ...Array(rareReps).fill(rarePool).flat(),
        ...Array(epicReps).fill(epicPool).flat(),
        ...Array(legendaryReps).fill(legendaryPool).flat(),
      ]
    : [
        ...Array(commonReps).fill(commonPool).flat(),
        ...Array(uncommonReps).fill(uncommonPool).flat(),
        ...Array(rareReps).fill(rarePool).flat(),
        ...Array(epicReps).fill(epicPool).flat(),
        ...Array(legendaryReps).fill(legendaryPool).flat(),
      ];

  if (player?.fabledForgeUnlocked && depth >= 60 && Math.random() < 0.12) weighted.push(...fabledPool);
  if (player?.masterfulForgeUnlocked && depth >= 150 && Math.random() < 0.025) weighted.push(...masterfulPool);
  if (player?.godhoodForgeUnlocked && depth >= 300 && Math.random() < 0.0025) weighted.push(...godhoodPool);

  const baseSlots = 4 + extraSlots;
  let shuffled = [...weighted].sort(() => Math.random() - 0.5).slice(0, baseSlots)
    .map(it => (it.type === 'skillbook' ? makeItemInstance(it) : makeScaledItemInstance(it, depth)));

  // Every merchant displays one family-balanced equipment feature. This is
  // deliberately additional to their ordinary stock so unlocking a niche slot
  // immediately makes its items realistically findable rather than diluting it.
  const featuredRarity = depth < 12 ? 'common' : depth < 30 ? 'uncommon' : depth < 60 ? 'rare' : 'epic';
  const featuredBase = pickBalancedGear(player, featuredRarity);
  if (featuredBase) {
    const featured = makeScaledItemInstance(featuredBase, depth);
    featured.price = Math.round((featuredRarity === 'epic' ? 220 : featuredRarity === 'rare' ? 95 : featuredRarity === 'uncommon' ? 35 : 15) * scale * discount);
    shuffled.push(featured);
  }

  // A merchant occasionally prices an object he cannot explain. Its name,
  // law and stats are generated from one persistent key, just like drops.
  const impossibleMerchantChance = Math.min(0.06, 0.01 + depth * 0.0001);
  if (Math.random() < impossibleMerchantChance) {
    const impossible = makeProceduralWeapon(depth, depth >= 100 ? 'epic' : 'rare', player);
    impossible.price = Math.round((300 + depth * 5) * discount);
    shuffled.push(impossible);
  }

  // Smarter Merchants is deliberately additive: it never replaces an item
  // that the older Better Merchant tree paid for.
  if (player?.smarterMerchantsUnlocked) {
    const smartBookPool = depth >= 35 ? [...COMMON_SKILLBOOKS, ...RARE_SKILLBOOKS] : COMMON_SKILLBOOKS;
    const smartBook = makeItemInstance(pickRandom(smartBookPool));
    smartBook.price = Math.round((smartBook.rarity === 'rare' ? 95 : 15) * scale * discount);
    smartBook.smartMerchantSlot = true;
    shuffled.push(smartBook);
    if (Math.random() < .05) {
      shuffled.push({ id:'sealed_chest', uid:uid('merchant_chest'), name:'Sealed Chest', type:'chestStock', rarity:'rare', price:Math.round(125 * scale * discount), emoji:'🧰', smartMerchantSlot:true });
    }
  }

  shuffled = recycleLearnedSpellBooks(shuffled, player);

  shuffled = shuffled.map(it => applyCoinMutations(applyMerchantPerfected(it, player?.merchantPerfectedChance || 0), player));
  if (player?.petHatsUnlocked && (player.petHats || []).length < PET_HAT_LIMIT) {
    const hat = generatePetHat(depth, player);
    hat.price = Math.round((PET_HAT_PRICE[hat.rarity] || PET_HAT_PRICE.common) * (1 + depth * 0.012) * discount);
    shuffled.push(hat);
  }
  shuffled.push({ id: 'health_potion', name: 'Health Potion', type: 'potion', rarity: 'common', price: Math.round(10 * discount), uid: uid('hp') });
  shuffled.push({ id: 'greater_potion', name: 'Greater Elixir', type: 'greaterPotion', rarity: 'rare', price: Math.round(35 * discount), uid: uid('gp') });

  const sellsThrowables = bmUnlocked.some(id => BETTER_MERCHANT_TREE.find(n => n.id === id)?.effect.sellsThrowables);
  const sellsBullets = bmUnlocked.some(id => BETTER_MERCHANT_TREE.find(n => n.id === id)?.effect.sellsBullets);
  const sellsArrows = bmUnlocked.some(id => BETTER_MERCHANT_TREE.find(n => n.id === id)?.effect.sellsArrows);

  if (sellsThrowables) {
    shuffled.push({ id: 'throwing_knives', name: 'Throwing Knives (x5)', type: 'throwableStock', count: 5, rarity: 'common', atk: THROWABLES[0].atk, price: Math.round(20 * discount), uid: uid('knives') });
  }
  if (sellsBullets && player && player.keyItems && player.keyItems.includes('handcannon')) {
    shuffled.push({ id: 'bullets', name: 'Bullets (x5)', type: 'ammoStock', ammoKey: 'bullets', count: 5, rarity: 'common', price: Math.round(18 * discount), uid: uid('bullets') });
  }
  if (sellsArrows && player && player.keyItems && player.keyItems.includes('bow')) {
    shuffled.push({ id: 'arrows', name: 'Arrows (x5)', type: 'ammoStock', ammoKey: 'arrows', count: 5, rarity: 'common', price: Math.round(15 * discount), uid: uid('arrows') });
  }
  return shuffled;
}

function generateCollectorOffers(player, depth) {
  const scale = 1 + depth * 0.05;
  const owned = [];
  Object.keys(COLLECTIBLE_META).forEach(cat => {
    (player.collectibles[cat] || []).forEach(idx => owned.push({ category: cat, index: idx }));
  });
  if (owned.length === 0) return [];
  const offers = [];
  for (let i = 0; i < 3; i++) {
    const costCount = 1 + Math.floor(Math.random() * 2);
    const shuffledOwned = [...owned].sort(() => Math.random() - 0.5);
    const cost = shuffledOwned.slice(0, Math.min(costCount, shuffledOwned.length));
    const r = Math.random();
    let reward;
    if (r < 0.4) reward = { type: 'gold', amount: Math.round((20 + cost.length * 18) * scale) };
    else if (r < 0.6) reward = { type: 'potion', amount: cost.length };
    else if (r < 0.75) reward = { type: 'greaterPotion', amount: 1 };
    else if (r < 0.93) reward = { type: 'item', item: makeItemInstance(pickBalancedGear(player, 'rare')) };
    else reward = { type: 'item', item: makeItemInstance(pickBalancedGear(player, 'epic')) };
    offers.push({ id: uid('offer'), cost, reward });
  }
  return offers;
}

function generateCollectibleSaleOffers(player, depth) {
  if (!player?.unoReversoUnlocked) return [];
  const discount = player.tradeSecretsUnlocked ? 0.8 : 1;
  const missing = [];
  Object.keys(COLLECTIBLE_META).forEach(category => {
    const owned = player.collectibles?.[category] || [];
    for (let index = 0; index < 50; index++) if (!owned.includes(index)) missing.push({ category, index });
  });
  const offerCount = player.fullHouseUnlocked ? 5 : 3;
  return [...missing].sort(() => Math.random() - .5).slice(0, offerCount).map(specimen => ({
    ...specimen,
    id:uid('collector_sale'),
    price:Math.max(1, Math.round((85 + depth * 2.5) * (1 + specimen.index / 125) * discount)),
  }));
}

function generateSubcollectibleSaleOffers(player, depth) {
  if (!player?.cabinetReversalUnlocked) return [];
  const missing = [];
  Object.keys(SUBCOLLECTIBLE_META).forEach(category => {
    if (!SUBCOLLECTIBLE_META[category].unlock(player)) return;
    const owned = player.subcollectibles?.[category] || [];
    for (let index = 0; index < 25; index++) if (!owned.includes(index)) missing.push({ category, index });
  });
  if (!missing.length) return [];
  const count = player.doubleReversalUnlocked ? 2 : 1;
  const discount = player.tradeSecretsUnlocked ? 0.8 : 1;
  return [...missing].sort(() => Math.random() - .5).slice(0, count).map(specimen => ({
    ...specimen,
    id:uid('cabinet_sale'),
    price:Math.max(1, Math.round((180 + depth * 4) * (1 + specimen.index / 80) * discount)),
  }));
}

function describeReward(reward) {
  if (reward.type === 'gold') return `For: ${reward.amount}g`;
  if (reward.type === 'potion') return `For: ${reward.amount} Health Potion${reward.amount > 1 ? 's' : ''}`;
  if (reward.type === 'greaterPotion') return 'For: 1 Greater Elixir';
  if (reward.type === 'item') return `For: ${reward.item.name}`;
  return '';
}

function generateTreasureLoot(depth, player) {
  const mult = 1 + (depth - 1) * 0.12;
  const gold = Math.round((30 + Math.random() * 40) * mult);
  let items = [makeScaledItemInstance(pickBalancedGear(player, 'rare'), depth)];
  if (Math.random() < 0.3) items.push(makeItemInstance(pickRandom(RARE_SKILLBOOKS)));
  if (Math.random() < 0.35 + luckBonus(player)) items.push(makeScaledItemInstance(pickBalancedGear(player, 'epic'), depth));
  if (Math.random() < 0.04 + luckBonus(player) * 0.08) items.push(makeProceduralWeapon(depth, depth >= 80 ? 'epic' : 'rare', player));
  items = applyFactorySealedToItems(items, player && player.factorySealedChance);
  items = applyCoinMutationsToItems(items, player);
  const potions = 1 + Math.floor(Math.random() * 2);
  const greaterPotions = Math.random() < 0.5 ? 1 : 0;
  return { gold, items, potions, greaterPotions };
}

// Coins 4 — Grand Library: every normal skillbook, plus exclusive tomes.
function generateLibraryStock(depth, player) {
  const scale = 1 + depth * 0.04;
  const ledgerDiscount = (player.keyItems && player.keyItems.includes('merchant_ledger')) ? 0.85 : 1;
  const commonStock = COMMON_SKILLBOOKS.map(b => ({ ...b, price: Math.round(20 * scale * ledgerDiscount), uid: uid(b.id) }));
  const rareStock = RARE_SKILLBOOKS.map(b => ({ ...b, price: Math.round(110 * scale * ledgerDiscount), uid: uid(b.id) }));
  let exclusiveCount = (player.keyItems && player.keyItems.includes('archivists_key')) ? 3 : 2;
  if (player.bannedBooksUnlocked) exclusiveCount += 1;
  const exclusivePool = [...EXCLUSIVE_LIBRARY_BOOKS, ...(player.bannedBooksUnlocked ? BANNED_BOOKS : [])];
  const exclusiveStock = [...exclusivePool]
    .sort(() => Math.random() - 0.5)
    .slice(0, exclusiveCount)
    .map(b => ({ ...b, price: Math.round(280 * scale * ledgerDiscount), uid: uid(b.id) }));
  return recycleLearnedSpellBooks([...commonStock, ...rareStock, ...exclusiveStock], player);
}

// Figures 3 — Wheel of Fortune: one spin, with family-balanced gear prizes.
function generateWheelReward(depth, player) {
  const r = Math.random();
  if (r < 0.35) {
    return { type: 'gold', amount: Math.round((40 + Math.random() * 60) * (1 + (depth - 1) * 0.08)) };
  } else if (r < 0.55) {
    return { type: 'book', item: makeItemInstance(pickRandom([...COMMON_SKILLBOOKS, ...RARE_SKILLBOOKS])) };
  } else if (r < 0.8) {
    return { type: 'gear', item: makeScaledItemInstance(pickBalancedGear(player, 'rare'), depth) };
  }
  return { type: 'gear', item: makeScaledItemInstance(pickBalancedGear(player, 'epic'), depth) };
}

// PRESTIGE RELIC FORGE — generated relics use a closed point budget. Depth
// changes price and provenance, never raw power. A curse grants at most two
// extra budget points and applies its penalty immediately, so no generated
// combination can silently outgrow the authored relic economy.
const PROCEDURAL_RELIC_RARITIES = [
  { rarity:'common', budget:4, icon:'◈' }, { rarity:'uncommon', budget:6, icon:'◇' },
  { rarity:'rare', budget:8, icon:'✧' }, { rarity:'epic', budget:10, icon:'♜' },
];
const PROCEDURAL_RELIC_AFFIXES = [
  { id:'vitality', cost:1, max:4, key:'maxHp', amount:5, text:n=>`+${n} max HP` },
  { id:'violence', cost:1, max:4, key:'atk', amount:1, text:n=>`+${n} ATK` },
  { id:'shelter', cost:1, max:4, key:'def', amount:1, text:n=>`+${n} DEF` },
  { id:'fortune', cost:1, max:4, key:'luck', amount:2, text:n=>`+${n} Luck` },
  { id:'evasion', cost:2, max:3, key:'dodge', amount:1, text:n=>`+${n}% dodge` },
  { id:'avarice', cost:2, max:2, key:'goldBonus', amount:.03, text:n=>`+${Math.round(n*100)}% gold` },
  { id:'memory', cost:2, max:2, key:'xpBonus', amount:.03, text:n=>`+${Math.round(n*100)}% XP` },
];
const PROCEDURAL_RELIC_CURSES = [
  { id:'frailty', name:'Frailty', credit:2, effect:{maxHp:-10}, text:'−10 max HP' },
  { id:'blunting', name:'Blunting', credit:2, effect:{atk:-2}, text:'−2 ATK' },
  { id:'crumbling', name:'Crumbling', credit:2, effect:{def:-2}, text:'−2 DEF' },
  { id:'misfortune', name:'Misfortune', credit:2, effect:{luck:-4}, text:'−4 Luck' },
];
const PROCEDURAL_RELIC_PREFIXES = ['Ashen','Hollow','Pilgrim’s','Unlicensed','Moon-Buried','Redacted','Warden’s','Impossible','Saltbound','Last'];
const PROCEDURAL_RELIC_CORES = ['Astrolabe','Fingerbone','Seal','Lantern','Hourglass','Icon','Reliquary','Compass','Witness','Chalice','Key','Idol'];
const PROCEDURAL_RELIC_EPITHETS = ['of the Ninth Door','That Remembers','from Below the Map','of Honest Debts','Without a Saint','of the Long Descent','That Refused Burial','of Returning Tides'];

function proceduralRelicRng(seed) {
  let value = seed >>> 0;
  return () => {
    value += 0x6D2B79F5;
    let t = value;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function makeProceduralRelic(depth, forgeTier, salt=0) {
  const originBiome = currentBiome(depth);
  const seed = hashStr(`relic:${depth}:${forgeTier}:${salt}:${Math.random()}`);
  const rng = proceduralRelicRng(seed);
  const maxRarityIndex = Math.min(3, Math.max(0, forgeTier - 1));
  const weights = [60, 26, 10, 4].slice(0, maxRarityIndex + 1);
  let roll = rng() * weights.reduce((sum, value) => sum + value, 0);
  let rarityIndex = 0;
  for (let index = 0; index < weights.length; index++) { roll -= weights[index]; if (roll <= 0) { rarityIndex = index; break; } }
  const meta = PROCEDURAL_RELIC_RARITIES[rarityIndex];
  const curse = forgeTier >= 4 && rng() < .2 ? PROCEDURAL_RELIC_CURSES[Math.floor(rng() * PROCEDURAL_RELIC_CURSES.length)] : null;
  const budget = meta.budget + (curse?.credit || 0);
  let remaining = budget;
  const stacks = {};
  while (remaining > 0) {
    const candidates = PROCEDURAL_RELIC_AFFIXES.filter(affix => affix.cost <= remaining && (stacks[affix.id] || 0) < affix.max);
    if (!candidates.length) break;
    const affix = candidates[Math.floor(rng() * candidates.length)];
    stacks[affix.id] = (stacks[affix.id] || 0) + 1;
    remaining -= affix.cost;
  }
  const effect = { ...(curse?.effect || {}) };
  const affixes = PROCEDURAL_RELIC_AFFIXES.filter(affix => stacks[affix.id]).map(affix => {
    const amount = affix.amount * stacks[affix.id];
    effect[affix.key] = (effect[affix.key] || 0) + amount;
    return { id:affix.id, stacks:stacks[affix.id], cost:affix.cost * stacks[affix.id], text:affix.text(amount) };
  });
  const prefix = PROCEDURAL_RELIC_PREFIXES[seed % PROCEDURAL_RELIC_PREFIXES.length];
  const core = PROCEDURAL_RELIC_CORES[Math.floor(seed / 17) % PROCEDURAL_RELIC_CORES.length];
  const epithet = PROCEDURAL_RELIC_EPITHETS[Math.floor(seed / 101) % PROCEDURAL_RELIC_EPITHETS.length];
  const biome = biomeAt(originBiome);
  const ecology = biomeEcology(originBiome);
  const name = `${prefix} ${core} ${epithet}`;
  const benefitText = affixes.map(affix => affix.text).join(' · ');
  const curseText = curse ? ` · CURSE — ${curse.text}` : '';
  return {
    id:`proc_relic_${seed.toString(36)}`, name, type:'relic', icon:meta.icon, rarity:meta.rarity,
    proceduralRelic:true, cursed:!!curse, curseName:curse?.name || null, effect, affixes,
    powerBudget:budget, spentBudget:budget - remaining, originBiome, seed,
    desc:`${benefitText}${curseText}. Found in ${biome.name}, where ${ecology.resource.toLowerCase()} settles into the oldest objects. Budget ${budget - remaining}/${budget}.`,
  };
}

function ProceduralRelicIcon({ relic, size=40, idSalt='relic', decorative=false }) {
  const seed=Number(relic?.seed)||hashStr(relic?.id||relic?.name||'relic');
  const rarity=rarityColorFor(relic?.rarity);
  const origin=Number.isInteger(relic?.originBiome)?relic.originBiome:0;
  const local=biomeAccent(origin);
  const id=`proc-relic-${seed}-${hashStr(String(idSalt))}`;
  const variant=seed%6;
  const shapes=[
    'M32 4 L50 15 L55 39 L42 59 L19 56 L8 37 L14 14 Z',
    'M32 3 L44 20 L59 25 L48 43 L47 59 L28 53 L12 59 L14 39 L4 25 L23 19 Z',
    'M19 6 L45 6 L53 20 L47 55 L32 61 L17 55 L11 20 Z',
    'M32 4 Q52 9 57 30 Q55 52 32 61 Q9 52 7 30 Q12 9 32 4 Z',
    'M32 3 L60 32 L32 61 L4 32 Z',
    'M10 11 L54 11 L48 31 L55 54 L34 49 L15 58 L17 34 Z',
  ];
  const facets=4+(seed%5);
  return <svg width={size} height={size} viewBox="0 0 64 64" role={decorative?undefined:'img'} aria-hidden={decorative?'true':undefined} aria-label={decorative?undefined:`Generated relic: ${relic.name}`} style={{display:'block',flex:'0 0 auto',filter:`drop-shadow(0 0 ${Math.max(3,size/10)}px ${rarity}99)`}}>
    {!decorative&&<title>{relic.name}</title>}
    <defs><linearGradient id={`${id}-body`} x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor={shadeGearColour(local,-.3)}/><stop offset=".42" stopColor={local}/><stop offset=".7" stopColor={shadeGearColour(rarity,.3)}/><stop offset="1" stopColor={shadeGearColour(rarity,-.35)}/></linearGradient><radialGradient id={`${id}-core`}><stop offset="0" stopColor="#fff"/><stop offset=".28" stopColor={rarity}/><stop offset="1" stopColor={local} stopOpacity=".18"/></radialGradient></defs>
    <path d={shapes[variant]} fill={`url(#${id}-body)`} stroke={relic.cursed?'#e06a6a':'#111827'} strokeWidth="2.3" strokeLinejoin="round"/>
    <circle cx="32" cy="32" r={11+(seed%5)} fill={`url(#${id}-core)`} stroke="#f8fafc" strokeWidth="1" opacity=".9"/>
    {Array.from({length:facets},(_,i)=>{const a=(Math.PI*2*i/facets)+(seed%17)/17;const x=32+Math.cos(a)*(20+(i%2)*4),y=32+Math.sin(a)*(20+(i%2)*4);return <g key={i}><path d={`M32 32 L${x.toFixed(1)} ${y.toFixed(1)}`} stroke="#f8fafc" strokeWidth=".7" opacity=".38"/><circle cx={x} cy={y} r="1.7" fill={i%2?rarity:local} stroke="#fff" strokeWidth=".4"/></g>;})}
    <path d="M17 17 Q32 7 47 17" fill="none" stroke="#fff" strokeWidth="1.2" opacity=".45"/>
    {relic.cursed&&<g stroke="#ff8da1" strokeWidth="1.6" fill="none"><path d="M13 20 L24 28 L18 38 L31 45 L27 58"/><path d="M50 15 L41 25 L47 33 L38 41"/></g>}
    <text x="32" y="36" textAnchor="middle" fontSize="11" fontWeight="900" fill="#111827" stroke="#fff" strokeWidth=".35">{relic.icon||'✧'}</text>
  </svg>;
}

// Stamps 3 — Relic Room: choose exactly one relic from a small paid offering.
function generateRelicOffers(player, depth) {
  const ownedIds = player.keyItems || [];
  const pool = ALL_RELICS.filter(r => !ownedIds.includes(r.id));

  const cursedChance = depth < 12 ? 0 : Math.min(0.18, 0.03 + depth * 0.003);
  const rarityWeight = { common: 62, uncommon: 28, rare: 10 };
  const available = [...pool];
  const offers = [];

  while (offers.length < Math.min(4, available.length)) {
    const weighted = available.map(r => {
      let weight = rarityWeight[r.rarity] || 1;
      if (r.cursed) weight *= cursedChance > 0 ? 1.0 : 0.001;
      else if (cursedChance > 0) weight *= 1 - cursedChance * 0.35;
      return { r, weight };
    });
    const total = weighted.reduce((sum, x) => sum + x.weight, 0);
    let roll = Math.random() * total;
    let chosen = weighted[weighted.length - 1].r;
    for (const entry of weighted) {
      roll -= entry.weight;
      if (roll <= 0) { chosen = entry.r; break; }
    }
    available.splice(available.indexOf(chosen), 1);
    offers.push(chosen);
  }

  const scale = 1 + depth * 0.045;
  const pricedAuthored = offers.map(r => {
    const base = r.rarity === 'rare' ? 300 : r.rarity === 'uncommon' ? 190 : 110;
    const curseDiscount = r.cursed ? 0.62 : 1;
    return { ...r, price: Math.max(40, Math.round((base + Math.random() * base * 0.35) * scale * curseDiscount)) };
  });
  const forgeTier = Math.min(5, player.relicForgeTier || 0);
  if (!forgeTier) return pricedAuthored;
  const generatedCount = forgeTier >= 5 ? 2 : 1;
  const generated = Array.from({length:generatedCount}, (_, index) => {
    const relic = makeProceduralRelic(depth, forgeTier, index);
    const base = relic.rarity === 'epic' ? 420 : relic.rarity === 'rare' ? 300 : relic.rarity === 'uncommon' ? 190 : 110;
    return { ...relic, price:Math.max(45, Math.round(base * scale * (relic.cursed ? .68 : 1))) };
  });
  return [...pricedAuthored.slice(0, Math.max(0, 4 - generatedCount)), ...generated];
}

// Figures 4 — Deluxe Merchant: absurdly expensive, absurdly strong fixed
// stock. Both stats and price scale with depth, same as the regular
// Merchant and Grand Library, so it stays worth the splurge at any depth
// it happens to appear rather than being frozen at its base numbers.
function generateDeluxeMerchantStock(depth, player) {
  const scale = 1 + depth * 0.04;
  const ledgerDiscount = (player && player.keyItems && player.keyItems.includes('merchant_ledger')) ? 0.85 : 1;
  return DELUXE_MERCHANT_STOCK.filter(it => it.type !== 'bracelet' || (player?.bodyMods || []).includes('wrists')).map(it => {
    const priced = { ...it, price: Math.round(it.price * scale * ledgerDiscount) };
    let out = priced.type === 'skillbook' ? makeItemInstance(priced) : makeScaledItemInstance(priced, depth);
    return applyCoinMutations(applyMerchantPerfected(out, player?.merchantPerfectedChance || 0), player);
  });
}

const ENCOUNTER_FORMATIONS = [
  {id:'phalanx',icon:'🛡️',name:'Bone Phalanx',desc:'The line shares its armour.',apply:(enemy,i,count)=>({def:1+.08*(count-1),hp:1.04,atk:.98})},
  {id:'hunting_pack',icon:'🐺',name:'Hunting Pack',desc:'Every living flank makes the attack sharper.',apply:(enemy,i,count)=>({def:.96,hp:.98,atk:1+.07*(count-1)})},
  {id:'sacrificial',icon:'🕯️',name:'Sacrificial Geometry',desc:'The rear creature grows fat on the weakness of the front.',apply:(enemy,i,count)=>i===count-1?{def:1.16,hp:1.22,atk:1.18}:{def:.82,hp:.80,atk:.94}},
  {id:'ambush',icon:'🗡️',name:'Crossfire Ambush',desc:'They have rehearsed the first exchange.',apply:()=>({def:.92,hp:.96,atk:1.17})},
  {id:'procession',icon:'🔔',name:'Funeral Procession',desc:'They carry offerings and refuse to break step.',apply:()=>({def:1.07,hp:1.08,atk:.96,gold:1.22})},
  {id:'choir',icon:'🎼',name:'Resonant Choir',desc:'Their overlapping voices make every death instructive.',apply:()=>({def:1.03,hp:1.04,atk:1.04,xp:1.20})},
  {id:'crescent',icon:'🌙',name:'Predator Crescent',desc:'The centre holds while the edges bite.',apply:(enemy,i,count)=>i===Math.floor(count/2)?{def:1.17,hp:1.15,atk:.95}:{def:.96,hp:.98,atk:1.16}},
  {id:'disagreement',icon:'⚡',name:'Armed Disagreement',desc:'They are fighting you and each other with equal conviction.',apply:(enemy,i)=>({def:.88,hp:.92,atk:1.20,gold:1.10,xp:1.10})},
];

function applyEncounterFormation(enemies, depth) {
  if(enemies.length<=1)return {enemies,formation:{id:'solitary',icon:'◉',name:'Solitary Territory',desc:'One organism has claimed the entire chamber.'}};
  const formation=ENCOUNTER_FORMATIONS[hashStr(`${depth}|${enemies.map(e=>e.baseId).join('|')}|formation`)%ENCOUNTER_FORMATIONS.length];
  return {formation,enemies:enemies.map((enemy,index)=>{
    const mult=formation.apply(enemy,index,enemies.length)||{};
    const maxHp=Math.max(1,Math.round(enemy.maxHp*(mult.hp||1)));
    return {...enemy,hp:maxHp,maxHp,atk:Math.max(1,Math.round(enemy.atk*(mult.atk||1))),def:Math.max(0,Math.round(enemy.def*(mult.def||1))),gold:Math.max(0,Math.round(enemy.gold*(mult.gold||1))),xp:Math.max(1,Math.round(enemy.xp*(mult.xp||1))),formationId:formation.id,formationName:formation.name};
  })};
}

function factionPactFor(player, biomeIndex) {
  return [...(player?.factionPacts||[])].reverse().find(pact=>pact.biomeIndex===biomeIndex)||null;
}

function factionPactEffect(player, biomeIndex, key) {
  const pact=factionPactFor(player,biomeIndex);
  return pact?.boonKey===key?Number(pact.boonValue||0):0;
}

const BIOME_MEMORY_TIERS = [
  {score:0,icon:'○',name:'Unknown Footsteps',desc:'The region has not learned your gait.'},
  {score:10,icon:'◔',name:'A Recognised Disturbance',desc:'Doors begin opening before you reach them.'},
  {score:30,icon:'◑',name:'A Local Problem',desc:'Predators exchange warnings using your name.'},
  {score:75,icon:'◕',name:'The Returning Calamity',desc:'The food web now includes surviving you.'},
  {score:150,icon:'●',name:'A Permanent Folklore',desc:'The biome has mistaken your history for natural law.'},
];

function biomeMemoryFor(player, biomeIndex) {
  return player?.biomeMemories?.[biomeIndex]||{kills:0,events:0,victories:0,retreats:0,champions:0,lastDecision:null,lastChampion:null,lastOutcome:null};
}

function biomeMemoryScore(memory) {
  return (memory.kills||0)+(memory.events||0)*8+(memory.victories||0)*4+(memory.retreats||0)*2+(memory.champions||0)*10;
}

function biomeMemoryTier(memory) {
  const score=biomeMemoryScore(memory);
  let tier=BIOME_MEMORY_TIERS[0];
  BIOME_MEMORY_TIERS.forEach(candidate=>{if(score>=candidate.score)tier=candidate;});
  return {...tier,index:BIOME_MEMORY_TIERS.indexOf(tier),score};
}

function memoryCombatProfile(player, biomeIndex) {
  const tier=biomeMemoryTier(biomeMemoryFor(player,biomeIndex));
  return {tier,atkRate:tier.index*.025,goldRate:tier.index*.04,xpRate:tier.index*.02,enemyAtkRate:Math.max(0,tier.index-2)*.015};
}

function recordBiomeMemory(player, biomeIndex, kind, detail=null) {
  const memories={...(player.biomeMemories||{})};
  const previous=biomeMemoryFor(player,biomeIndex);
  const next={...previous};
  if(kind==='kill')next.kills=(next.kills||0)+1;
  if(kind==='event'){next.events=(next.events||0)+1;next.lastDecision=detail;next.lastOutcome='The region remembers a decision.';}
  if(kind==='victory'){next.victories=(next.victories||0)+1;next.lastOutcome='The chamber remembers who left standing.';}
  if(kind==='retreat'){next.retreats=(next.retreats||0)+1;next.lastOutcome='Something local remembers giving chase.';}
  if(kind==='champion'){next.champions=(next.champions||0)+1;next.lastChampion=detail;next.lastOutcome='A named inhabitant was removed from the story.';}
  next.lastTouchedDepth=detail?.depth||next.lastTouchedDepth||null;
  memories[biomeIndex]=next;
  return {...player,biomeMemories:memories};
}

function biomeMemoryLore(player, biomeIndex) {
  const memory=biomeMemoryFor(player,biomeIndex),tier=biomeMemoryTier(memory),biome=biomeAt(biomeIndex);
  if(tier.index===0)return `${biome.name} has not yet decided what you are.`;
  const fragments=[`${biome.name} records you as ${tier.name.toLowerCase()}.`,`${memory.kills||0} local deaths have been attached to your name.`,memory.lastDecision?`Its most recent argument with you ended: “${memory.lastDecision}.”`:null,memory.lastChampion?`${memory.lastChampion} is now remembered mostly by its absence.`:null,memory.lastOutcome].filter(Boolean);
  return fragments.join(' ');
}

const WORLD_EVENT_KINDS = ['faction_parley','ecology_crisis','living_weather','memory_well','lost_expedition','local_god','merchant_funeral','future_mirror'];

const CONTRACT_VERBS=['Cull','Quiet','Catalogue','Outlive','Correct','Discourage','Make an Example of','Reduce the Population of'];
const CONTRACT_REASONS=['keeps eating the surveyors','has violated an extremely local treaty','is upsetting the decomposers','refuses to pay the tooth tithe','has become too memorable','is breeding in the punctuation','knows where the faction stores its maps','has started voting twice'];

function generateBiomeContract(depth) {
  const biomeIndex=currentBiome(depth),biome=biomeAt(biomeIndex),ecology=biomeEcology(biomeIndex),factions=biomeFactions(biomeIndex),phenomenon=biomePhenomenon(biomeIndex);
  const seed=hashStr(`${depth}|${biomeIndex}|contract`),issuer=factions[seed%factions.length];
  const target=3+(Math.floor(seed/17)%5),gold=Math.round((55+depth*3.2)*(1+target*.08)),xp=Math.round((35+depth*2.1)*(1+target*.06));
  const subject=[ecology.predator,ecology.invasive,`${phenomenon.name} casualties`,`anything carrying local teeth`][Math.floor(seed/71)%4];
  return {id:`contract_${biomeIndex}_${depth}_${seed.toString(36)}`,biomeIndex,biomeName:biome.name,issuerId:issuer.id,issuerName:issuer.name,issuerIcon:issuer.icon,title:`${CONTRACT_VERBS[Math.floor(seed/113)%CONTRACT_VERBS.length]} ${subject}`,desc:`${issuer.name} claims the local population ${CONTRACT_REASONS[Math.floor(seed/197)%CONTRACT_REASONS.length]}. Defeat ${target} enemies anywhere in ${biome.name}.`,target,progress:0,rewardGold:gold,rewardXp:xp,completed:false,claimed:false,phenomenonId:phenomenon.id};
}

function advanceContractsForKill(player, enemy, log) {
  const biomeIndex=currentBiome(enemy.depth||1);
  let payoutGold=0,payoutXp=0,completed=[];
  const contracts=(player.contracts||[]).map(contract=>{
    if(contract.completed||contract.biomeIndex!==biomeIndex)return contract;
    const progress=Math.min(contract.target,(contract.progress||0)+1),done=progress>=contract.target;
    if(done){payoutGold+=contract.rewardGold;payoutXp+=contract.rewardXp;completed.push(contract);}
    return {...contract,progress,completed:done,claimed:done};
  });
  const adjustedPayoutGold=Math.round(payoutGold*(1+(player.doohickeyGoldRate||0)));
  let next={...player,contracts,gold:player.gold+adjustedPayoutGold};
  if(payoutXp){const result=applyXp(next,payoutXp);next=result.player;}
  completed.forEach(contract=>{
    next=recordBiomeMemory(next,biomeIndex,'event',`Completed “${contract.title}”`);
    const contractGold=Math.round(contract.rewardGold*(1+(player.doohickeyGoldRate||0)));
    log.push(`${contract.issuerIcon} CONTRACT COMPLETE: ${contract.title} · +${contractGold}g · +${contract.rewardXp}xp. ${contract.issuerName} denies being impressed.`);
  });
  return next;
}

function generateWorldEvent(depth, player, forcedSeed=null) {
  const biomeIndex=currentBiome(depth),biome=biomeAt(biomeIndex),ecology=biomeEcology(biomeIndex),laws=biomeWorldLaws(biomeIndex),factions=biomeFactions(biomeIndex);
  const seed=forcedSeed===null?Math.floor(Math.random()*0xffffffff):forcedSeed;
  const kind=WORLD_EVENT_KINDS[hashStr(`${seed}|${depth}|event`)%WORLD_EVENT_KINDS.length];
  const scale=1+depth*.085;
  const gold=n=>Math.max(10,Math.round(n*scale));
  const xp=n=>Math.max(10,Math.round(n*(1+depth*.065)));
  let event;
  if(kind==='faction_parley') event={icon:'⚖️',name:'Parley at the Wrong Border',description:`${factions[0].name} and ${factions[1].name} have drawn competing borders through the same corridor. Both insist you are already a citizen.`,choices:[
    {id:'side_a',icon:factions[0].icon,name:`Back ${factions[0].name}`,desc:`They ${factions[0].doctrine}. Pact boon: ${factions[0].boon.label}.`,effect:{pact:factions[0],gold:gold(18)}},
    {id:'side_b',icon:factions[1].icon,name:`Back ${factions[1].name}`,desc:`They ${factions[1].doctrine}. Pact boon: ${factions[1].boon.label}.`,effect:{pact:factions[1],xp:xp(16)}},
    {id:'independent',icon:'🧭',name:'Recognise Neither Border',desc:'Walk directly through the negotiations and become a minor diplomatic incident.',effect:{bonusLuck:2,chests:1}},
  ]};
  else if(kind==='ecology_crisis') event={icon:'🌿',name:'A Food Web Comes Loose',description:`A migration of ${ecology.prey} has trapped ${ecology.predator} inside a dying stand of ${ecology.flora}. The decomposers are taking bets.`,choices:[
    {id:'cull',icon:'⚔️',name:`Cull the ${ecology.predator}`,desc:'Restore the old balance by making it somebody else’s problem.',effect:{atk:1,gold:gold(24),damagePct:.10}},
    {id:'protect',icon:'🛡️',name:`Protect the ${ecology.prey}`,desc:'Hold the line until the herd reaches cover.',effect:{def:1,maxHp:3,healPct:.30}},
    {id:'harvest',icon:'💎',name:`Harvest ${ecology.resource}`,desc:'The crisis has exposed a seam of valuable material. Ecology can file a complaint.',effect:{gearRarity:'rare',gold:gold(12),damagePct:.15}},
  ]};
  else if(kind==='living_weather') event={icon:'🌩️',name:'Weather With Intent',description:`The ${ecology.climate} gathers into a deliberate wall. Under ${laws[0].name}, it is legally considered a person.`,choices:[
    {id:'cross',icon:'🗡️',name:'Walk Straight Through',desc:'Take the shortest route and let survival teach the lesson.',effect:{xp:xp(30),atk:1,damagePct:.18}},
    {id:'shelter',icon:'🏕️',name:'Shelter and Observe',desc:'Lose time, recover fully, and learn how the storm hunts.',effect:{healPct:1,bonusLuck:1}},
    {id:'bottle',icon:'🧪',name:'Bottle the Weather',desc:'This is irresponsible, difficult and potentially useful.',effect:{potions:2,greaterPotions:1,chests:1,damagePct:.08}},
  ]};
  else if(kind==='memory_well') event={icon:'🪞',name:'The Well of Previous Visitors',description:`A black pool reflects everyone who entered ${biome.name} and failed to leave. One reflection has your face.`,choices:[
    {id:'remember',icon:'📖',name:'Accept Their Memories',desc:'Learn several deaths at once.',effect:{xp:xp(45),maxHp:2}},
    {id:'forget',icon:'🕊️',name:'Give the Well a Memory',desc:'Forget one old pain. Your body keeps the useful part.',effect:{healPct:1,def:1}},
    {id:'sell',icon:'🪙',name:'Sell the Reflections Their Names',desc:'The dead pay badly, but there are a lot of them.',effect:{gold:gold(55),bonusLuck:-1}},
  ]};
  else if(kind==='lost_expedition') event={icon:'⛺',name:'The Expedition That Arrived First',description:`A camp carries your name on its supply crates. Its journal describes your arrival tomorrow and ends mid-sentence.`,choices:[
    {id:'rescue',icon:'❤️',name:'Treat the Survivors',desc:'Nobody is visible, but the bandages still disappear from your hands.',effect:{potions:2,def:1,healPct:.35}},
    {id:'salvage',icon:'🎒',name:'Salvage the Camp',desc:'Take what your alternate self apparently packed for you.',effect:{gearRarity:'rare',gold:gold(20),chests:1}},
    {id:'bury',icon:'⚰️',name:'Bury the Empty Bedrolls',desc:'The biome accepts the ceremony even without bodies.',effect:{maxHp:4,bonusLuck:2}},
  ]};
  else if(kind==='local_god') event={icon:'🗿',name:'A Very Local God',description:`A shrine assembled from ${ecology.resource} claims dominion over precisely this room and no farther. Its theology is extremely focused.`,choices:[
    {id:'tithe',icon:'🪙',name:'Pay the Room-God',desc:`Offer ${gold(15)} gold for safe theological passage.`,effect:{costGold:gold(15),bonusLuck:3,chests:1}},
    {id:'defy',icon:'⚔️',name:'Challenge Its Jurisdiction',desc:'Win the legal argument by hitting the altar.',effect:{atk:2,damagePct:.24,gold:gold(10)}},
    {id:'listen',icon:'👂',name:'Attend the Entire Sermon',desc:'It has only one room to discuss, but very strong opinions about it.',effect:{xp:xp(50),maxHp:2}},
  ]};
  else if(kind==='merchant_funeral') event={icon:'⚱️',name:'The Merchant’s Funeral',description:`A funeral stall sells the possessions of a merchant who is standing behind it and objecting to every price.`,choices:[
    {id:'buy',icon:'💰',name:'Purchase Your Condolences',desc:`Pay ${gold(28)} gold for the item the deceased insists is cursed.`,effect:{costGold:gold(28),gearRarity:'epic'}},
    {id:'steal',icon:'🗡️',name:'Rob the Funeral',desc:'Morally poor. Financially excellent. The coffin bites.',effect:{gold:gold(70),damagePct:.20}},
    {id:'carry',icon:'🪦',name:'Help Carry the Coffin',desc:'It is heavier on the inside.',effect:{def:1,maxHp:3,potions:1}},
  ]};
  else event={icon:'🔮',name:'A Mirror Facing Tomorrow',description:`The glass shows you leaving ${biome.name} with equipment you do not own and a wound you have not received.`,choices:[
    {id:'duel',icon:'⚔️',name:'Fight the Reflection',desc:'It knows every move except the one you regret inventing.',effect:{atk:1,def:1,xp:xp(24),damagePct:.20}},
    {id:'shatter',icon:'💥',name:'Shatter Tomorrow',desc:'Collect the sharpest possibility.',effect:{gearRarity:'rare',gold:gold(24)}},
    {id:'ask',icon:'❓',name:'Ask What Comes Next',desc:'The answer is mostly directions and one useful warning.',effect:{chests:2,xp:xp(35),bonusLuck:1}},
  ]};
  return {type:'world_event',kind,eventId:`event_${depth}_${seed.toString(36)}`,eventSeed:seed,biomeIndex,lawIds:laws.map(l=>l.id),resolved:false,cleared:false,enemies:[],...event};
}

function generateRoom(depth, player) {
  if (depth % 6 === 0) {
    return { type: 'merchant', enemies: [], cleared: true, stock: generateMerchantStock(depth, player) };
  }
  if (depth % 9 === 0) {
    return { type: 'healer', enemies: [], cleared: true, petOffer:generateBiomePet(depth), petClaimed:false, contractOffer:generateBiomeContract(depth), contractAccepted:false };
  }
  if (player.figures4TreeUnlocked && Math.random() < 0.01) {
    return {
      type: 'deluxe_merchant',
      enemies: [],
      cleared: true,
      stock: generateDeluxeMerchantStock(depth, player),
    };
  }
  if (player.coins4TreeUnlocked && Math.random() < 0.06) {
    return { type: 'library', enemies: [], cleared: true, stock: generateLibraryStock(depth, player) };
  }
  if (player.figures3TreeUnlocked) {
    const wheelChance = 0.07 + ((player.keyItems || []).includes('gamblers_coin') ? 0.05 : 0);
    if (Math.random() < wheelChance) {
      return { type: 'wheel', enemies: [], cleared: false, spun: false, reward: generateWheelReward(depth, player) };
    }
  }
  // Abyssal Anomaly — available once the Atlas-side Abyssal Archive is unlocked
  // and the Figures 10 prestige tree has been started, with depth gating.
  if (player.abyssalArchiveUnlocked && player.abyssalBreachChance > 0 && depth >= 20 && Math.random() * 100 < player.abyssalBreachChance) {
    return generateAnomalyRoom(depth, player);
  }
  if (player.stamps3TreeUnlocked && Math.random() < 0.05) {
    return { type: 'relic', enemies: [], cleared: false, bought: false, offers: generateRelicOffers(player, depth) };
  }
  if (player.coins6TreeUnlocked && Math.random() < 0.04) {
    return { type: 'tunnel', enemies: [], cleared: false, used: false };
  }
  if (Math.random() < 0.10) return generateWorldEvent(depth, player);
  const compassBonus = (player.keyItems || []).includes('wanderers_compass');
  const dealerBonus = player.dealersChoiceUnlocked ? 0.05 : 0;
  if ((getCollectibleCount(player) > 0 || player.unoReversoUnlocked) && Math.random() < (compassBonus ? 0.15 : 0.1) + dealerBonus) {
    return { type: 'collector', enemies: [], cleared: true, offers: generateCollectorOffers(player, depth), saleOffers:generateCollectibleSaleOffers(player, depth), subSaleOffers:generateSubcollectibleSaleOffers(player, depth) };
  }
  if (Math.random() < (compassBonus ? 0.12 : 0.08)) {
    return { type: 'treasure', enemies: [], cleared: false, opened: false, loot: generateTreasureLoot(depth, player) };
  }
  const enemyCount = 1 + Math.floor(Math.random() * 3);
  const baseEnemies = pickUniqueEnemyTemplates(depth, enemyCount).map(template => scaleEnemy(template, depth));
  const encounter=applyEncounterFormation(baseEnemies,depth);
  return { type: 'combat', enemies:encounter.enemies, formation:encounter.formation, cleared: false, fled: false };
}

function applyXp(player, xpGain) {
  const adjustedXp = Math.max(0, Math.round((Math.round(xpGain) + (player.bonusXpFlat || 0)) * (1 + (player.doohickeyXpRate || 0))));
  let p = { ...player, xp: player.xp + adjustedXp };
  let leveled = false;
  while (p.xp >= p.xpNext) {
    p.xp -= p.xpNext;
    p.level += 1;
    p.maxHp += 10;
    p.hp = p.maxHp;
    p.atk += 2;
    p.def += 1;
    p.xpNext = Math.round(p.xpNext * 1.4);
    leveled = true;
  }
  return { player: p, leveled };
}

function describeEffect(eff) {
  const parts = [];
  if (eff.hp) parts.push(`+${eff.hp} max HP`);
  if (eff.atk) parts.push(`+${eff.atk} ATK`);
  if (eff.def) parts.push(`+${eff.def} DEF`);
  return `Permanently grants ${parts.join(', ')}.`;
}

