  p.cards9TreeUnlocked = !!prestige.cards9TreeUnlocked;
  p.bookRecyclingUnlocked = !!prestige.bookRecyclingUnlocked;
  p.coins10TreeUnlocked = !!prestige.coins10TreeUnlocked;
  const perfectedFinds = Array.isArray(prestige.perfectedFindsUnlocked) ? prestige.perfectedFindsUnlocked : (prestige.perfectedFindsUnlocked ? COINS10_TREE.map(n => n.id) : []);
  p.perfectedFindsTier = perfectedFinds.length;
