  p.figures13TreeUnlocked = !!prestige.figures13TreeUnlocked;
  p.multipets3Unlocked = !!prestige.multipets3Unlocked;
  p.figures14TreeUnlocked = !!prestige.figures14TreeUnlocked;
  p.multipets4Unlocked = !!prestige.multipets4Unlocked;
  p.figures15TreeUnlocked = !!prestige.figures15TreeUnlocked;
  p.smarterMerchantsUnlocked = !!prestige.smarterMerchantsUnlocked;
  p.figures16TreeUnlocked = !!prestige.figures16TreeUnlocked;
  p.petForagingUnlocked = !!prestige.petForagingUnlocked;
