function soulRewardBreakdown(maxDepthReached, level = 1, soulWindfallBonus = 0) {
  // Base: 1 Soul per 3 depths. Every complete 50 character levels now adds
  // another 20% to the payout, stacking additively with Soul Windfall.
  const base = Math.max(0, Math.floor((maxDepthReached - 1) / 3));
  const levelBands = Math.max(0, Math.floor((level || 1) / 50));
  const levelBonus = levelBands * 0.20;
  const multiplier = 1 + levelBonus + (soulWindfallBonus || 0);
  return { base, levelBands, levelBonus, windfallBonus:soulWindfallBonus || 0, multiplier, total:Math.round(base * multiplier) };
}

function soulsForRun(maxDepthReached, level = 1, soulWindfallBonus = 0) {
  return soulRewardBreakdown(maxDepthReached, level, soulWindfallBonus).total;
}

// Back with a Vengeance (Stamps 7): each new run has a small chance to
// start already holding the Vorpal Sword, a weapon exactly as strong as
// whatever was equipped the moment the previous run ended in death.
function rollBackWithAVengeance(prestige) {
  const chance = (prestige.backWithAVengeanceUnlocked || []).length; // 1 percentage point per tier
  if (chance <= 0 || !prestige.lastDeathWeapon) return null;
  if (Math.random() * 100 >= chance) return null;
  const dw = prestige.lastDeathWeapon;
  return { id: 'vorpal_sword', name: 'Vorpal Sword', type: 'weapon', rarity: dw.rarity || 'common', atk: dw.atk || 0, def: dw.def || 0, uid: uid('vorpal_sword'), sourceName: dw.name };
}

// Dimensional Gift (Cards 7): each new run has a small chance to start
// already holding one relic carried over from the moment the last run
// ended (whatever was in player.keyItems at death).
function rollDimensionalGift(prestige) {
  const chance = (prestige.dimensionalGiftUnlocked || []).length; // 1 percentage point per tier
  const pool = prestige.lastRunRelics || [];
  if (chance <= 0 || pool.length === 0) return null;
  if (Math.random() * 100 >= chance) return null;
  return pickRandom(pool);
}

// Applies a gifted relic's instant effect (if any) the same way finding it
// mid-run would, and adds it to keyItems.
function relicById(relicId, prestige=null) {
  return ALL_RELICS.find(r => r.id === relicId) || (prestige?.proceduralRelicArchive || []).find(r => r.id === relicId) || null;
}

function applyRelicEffect(player, relic) {
  if (!relic) return player;
  const e = relic.effect || {};
  const p = { ...player };
  if (e.maxHp) {
    p.maxHp = Math.max(1, p.maxHp + e.maxHp);
    p.hp = Math.min(p.maxHp, Math.max(1, p.hp + e.maxHp));
  }
  if (e.atk) p.atk = Math.max(0, p.atk + e.atk);
  if (e.def) p.def = Math.max(0, p.def + e.def);
  if (e.luck) p.bonusLuck = (p.bonusLuck || 0) + e.luck;
  if (e.dodge) p.dodgeChance = Math.min(75, (p.dodgeChance || 0) + e.dodge);
  if (e.goldBonus) p.relicGoldBonus = (p.relicGoldBonus || 0) + e.goldBonus;
  if (e.xpBonus) p.relicXpBonus = (p.relicXpBonus || 0) + e.xpBonus;
  return p;
}

function applyGiftedRelic(player, relicId, prestige=null) {
  const relic = relicById(relicId, prestige);
  let p = { ...player, keyItems: [...player.keyItems, relicId], proceduralRelics:relic?.proceduralRelic ? [...(player.proceduralRelics || []), relic] : (player.proceduralRelics || []) };
  if (relic) p = applyRelicEffect(p, relic);
  return p;
}

function freshState(prestige, preserveCollectibles, name) {
  const basePrestige = prestige || freshPrestige();
  const prevVisits = (basePrestige.biomeVisits && basePrestige.biomeVisits[0]) || 0;
  const usedPrestige = recordBiomeVisit(basePrestige, 0);
  const newVisits = usedPrestige.biomeVisits[0];
  const atlasMsgs = usedPrestige.atlasUnlocked ? atlasMilestoneLog(prevVisits, newVisits, 0) : [];
  let player = freshPlayer(usedPrestige, name);
  const vorpal = rollBackWithAVengeance(usedPrestige);
  if (vorpal) player = { ...player, weapon: vorpal };
  const giftedRelicId = rollDimensionalGift(usedPrestige);
  if (giftedRelicId) player = applyGiftedRelic(player, giftedRelicId, usedPrestige);
  if (preserveCollectibles) {
    player.collectibles = preserveCollectibles.collectibles;
    player.collectibleNames = preserveCollectibles.collectibleNames;
    player.collectibleOrigins = { ...(usedPrestige.collectibleOrigins || {}), ...(preserveCollectibles.collectibleOrigins || {}) };
    player.discoveryOrder = preserveCollectibles.discoveryOrder || [];
  }
  const isNaomi = (name || '').trim().toLowerCase() === 'naomi';
  const giftedRelicInfo = giftedRelicId ? relicById(giftedRelicId, usedPrestige) : null;
  return {
    player,
    prestige: usedPrestige,
    depth: 1,
    room: generateRoom(1, player),
    log: [
      `${player.name} steps through the threshold. Cold, wet air rushes up from the dark.`,
      ...(isNaomi ? ['✦ The dungeon recognizes you, Naomi. +10 ATK granted.'] : []),
      ...(vorpal ? [`⚔️ Back with a Vengeance! The Vorpal Sword (once your ${vorpal.sourceName}) is already in your hand — ${vorpal.atk} ATK, ${vorpal.def} DEF.`] : []),
      ...(giftedRelicInfo ? [`✨ Dimensional Gift! ${giftedRelicInfo.name} slips through from your last life, already yours.`] : []),
      ...atlasMsgs,
    ],
    gameOver: false,
    prestigeReady: false,
    selectedTarget: 0,
    narration: biomeIntroLine(0, newVisits - 1, player, 1),
    narrationLoading: false,
    biomeIntroId: 1,
    biomeChoicePending: false,
    loaded: true,
  };
}

function totalAtk(player) {
  const equippedAtk = equippedGearItems(player).reduce((sum, item) => sum + (Number(item?.atk) || 0), 0);
  const raw = player.atk + equippedAtk + Math.floor(getCollectibleCount(player) * (player.hoardersAtkRate || 0));
  const infiniteRate = (player.doohickeyDamageRate || 0) + (activePetOf(player) ? (player.doohickeyBondRate || 0) : 0);
  return Math.max(0, Math.round(raw * (1 + activePetEffect(player, 'atkRate') + infiniteRate)));
}
function totalDef(player) {
  const equippedDef = equippedGearItems(player).reduce((sum, item) => sum + (Number(item?.def) || 0), 0);
  const raw = player.def + equippedDef + Math.floor(getCollectibleCount(player) * (player.defensiveCollectingRate || 0));
  const infiniteRate = (player.doohickeyDefRate || 0) + (activePetOf(player) ? (player.doohickeyBondRate || 0) : 0);
  return Math.max(0, Math.round(raw * (1 + activePetEffect(player, 'defRate') + infiniteRate)));
}

/* =========================================================
   COMBAT HELPERS (shared by ATTACK / FLEE)
========================================================= */

function gearDodgeChance(player) {
  return equippedGearItems(player).reduce((sum, item) => sum + (Number(item?.dodge) || 0), 0);
}

function equippedGearItems(player) {
  return [player.weapon, player.weapon2, player.armor, player.chestpiece, player.greaves, player.footwear, player.headgear,
    player.ring1, player.ring2, player.ring3, player.ring4, player.ring5, player.earring, player.earring2,
    player.bracelet1, player.bracelet2, player.trinket, player.necklace].filter(Boolean);
}

function gearCritChance(player) {
  return equippedGearItems(player).reduce((sum, item) => sum + (Number(item.critChance) || 0), 0) + activePetEffect(player, 'critChance');
}

function gearThornsRate(player) {
  return Math.min(1, equippedGearItems(player).reduce((sum, item) => sum + (Number(item.thornsRate) || 0), 0));
}

function gearSoulLeechChance(player) {
  return equippedGearItems(player).reduce((sum, item) => sum + (Number(item.soulLeechChance) || 0), 0);
}

function equippedWeapons(player) {
  return [player.weapon, player.weapon2].filter(item => item && item.type === 'weapon');
}

function weaponProcTotal(player, key) {
  return equippedWeapons(player).reduce((sum, item) => sum + (Number(item[key]) || 0), 0);
}

function weaponProcChance(player, key) {
  return Math.min(100, weaponProcTotal(player, key));
}

function elementalDamageRate(player, element, includeWeapons = true) {
  return equippedGearItems(player).reduce((sum, item) => {
    if (!item || item.element !== element || !item.elementalDamage) return sum;
    if (!includeWeapons && ELEMENTAL_WEAPON_TYPES.has(item.type)) return sum;
    return sum + Number(item.elementalDamage || 0);
  }, 0);
}

function elementalAttackProfile(player, biomeIndex, includeWeapons = true) {
  const biomeProfile = biomeElementProfile(biomeIndex);
  const element = biomeProfile.weakness;
  const gearRate = Math.min(0.75, elementalDamageRate(player, element, includeWeapons));
  const petRate = activePetsOf(player).filter(pet => pet.element === element)
    .reduce((total, pet) => total + Number(petTraitEffect(pet).elementalRate || 0), 0);
  const masteryRate = gearRate + petRate > 0 ? Math.min(0.25, Number(player.elementalMastery?.[element] || 0)) : 0;
  const doohickeyCategory = DOOHICKEY_CATEGORY_KEYS.find(category => SUBCOLLECTIBLE_META[category]?.element === element);
  const cabinetRate = Number(player.doohickeyBonuses?.[doohickeyCategory] || 0) / 100;
  return { element, gearRate, petRate, masteryRate, cabinetRate, bonus:gearRate + petRate + masteryRate + cabinetRate };
}

function applyElementalDamage(baseDamage, player, target, includeWeapons = true) {
  const profile = elementalAttackProfile(player, currentBiome(target.depth || 1), includeWeapons);
  const resistedBonus=profile.bonus*Math.max(0,1-Number(target.mutationElementResist||0));
  const bonusDamage = resistedBonus > 0 ? Math.max(1, Math.round(baseDamage * resistedBonus)) : 0;
  return { ...profile, bonusDamage, resisted:Number(target.mutationElementResist||0)>0, total:baseDamage + bonusDamage };
}

function elementalWardProfile(player, biomeIndex) {
  const biomeProfile = biomeElementProfile(biomeIndex);
  const element = biomeProfile.affinity;
  const rate = Math.min(0.60, equippedGearItems(player).reduce((sum, item) =>
    item?.element === element ? sum + Number(item.elementalWard || 0) : sum, 0));
  return { element, rate };
}

function enemyTurn(player, enemies, log) {
  let p = player;
  const lb = luckBonus(p) * 0.5;
  const baseDodge = ((p.dodgeChance || 0) + gearDodgeChance(p) + activePetEffect(p, 'dodgeChance')) / 100;
  enemies.forEach(e => {
    if (e.hp > 0) {
      const localBiome=currentBiome(e.depth||1);
      const phenomenon=biomePhenomenon(localBiome);
      const remembered=memoryCombatProfile(p,localBiome);
      if(e.behaviour==='regenerator'&&e.hp<e.maxHp){const healed=Math.max(1,Math.round(e.maxHp*.06));e.hp=Math.min(e.maxHp,e.hp+healed);log.push(`🌱 The ${e.name} regenerates ${healed} HP.`);}
      const bb = bestiaryBonusVs(p, e.baseId);
      const pactDodge=factionPactEffect(p,localBiome,'dodgeChance');
      const dodge = baseDodge + bb.dodgeBonus / 100 + soulwellDodgeFor(p, e.baseId)+pactDodge+(phenomenon.playerDodge||0);
      let blocked = false;
      if (dodge > 0 && Math.random() < dodge) {
        blocked = true;
        log.push(`You dodge the ${e.name}'s attack entirely!`);
      }
      if (!blocked && p.abilities.includes('ironskin') && Math.random() < 0.15 + lb) {
        blocked = true;
        log.push(`Your skin turns to stone — the ${e.name}'s attack is deflected!`);
      }
      if (!blocked) {
        const petBlockChance = activePetEffect(p, 'blockChance');
        if (petBlockChance > 0 && Math.random() < petBlockChance) {
          blocked = true;
          const pet = activePetOf(p);
          log.push(`✨ ${pet?.name || 'Your companion'} intercepts the ${e.name}'s attack!`);
        }
      }
      if (!blocked) {
        const soulwellBlock = soulwellBlockChanceFor(p, e.baseId);
        if (soulwellBlock > 0 && Math.random() < soulwellBlock) {
          blocked = true;
          log.push(`🎰 A Soulwell ward flares — the ${e.name}'s attack is fully blocked!`);
        }
      }
      if (!blocked) {
        const packMult=e.behaviour==='pack_hunter'?1+Math.max(0,enemies.filter(other=>other.hp>0).length-1)*.10:1;
        const berserkMult=e.behaviour==='berserker'&&e.hp/e.maxHp<.5?1.35:1;
        const executeMult=e.behaviour==='executioner'&&p.hp/p.maxHp<.35?1.35:1;
        const hexProc=e.behaviour==='hexer'&&Math.random()<.30;
        const pactDef=factionPactEffect(p,localBiome,'defRate');
        const effectiveDef=Math.round(totalDef(p)*(1+pactDef)*bb.defMult*soulwellDefMultFor(p,e.baseId)*(hexProc ? .65 : 1));
        const unwardedDamage = Math.max(1,Math.round(damageRoll(Math.max(1,Math.round(e.atk*packMult*berserkMult*executeMult*(1+remembered.enemyAtkRate))),effectiveDef)*(phenomenon.incoming||1)));
        const ward = elementalWardProfile(p, currentBiome(e.depth || 1));
        const wardAbsorbed = ward.rate > 0 ? Math.round(unwardedDamage * 0.35 * ward.rate) : 0;
        const edmg = Math.max(0, unwardedDamage - wardAbsorbed);
        const physicianChance = (p.physicianChance || 0) / 100;
        if (physicianChance > 0 && Math.random() < physicianChance) {
          const healed = Math.min(p.maxHp - p.hp, edmg);
          if (healed > 0) {
            p = { ...p, hp: Math.min(p.maxHp, p.hp + healed) };
            log.push(`The ${e.name} strikes — but the blow heals you for ${healed} instead! (Physician)`);
          } else {
            log.push(`The ${e.name} strikes — the Physician turns the blow to nothing!`);
          }
        } else {
          p = { ...p, hp: Math.max(0, p.hp - edmg) };
          log.push(`The ${e.name} hits you for ${edmg}.${hexProc?' 🔮 Its hex ignores part of your defence.':''}${berserkMult>1?' 💢 Berserker rage!':''}${packMult>1?' 🐺 Pack bonus!':''}${executeMult>1?' 🪓 Executioner bonus!':''}${wardAbsorbed > 0 ? ` ${elementMeta(ward.element).icon} ${elementMeta(ward.element).name} Ward absorbs ${wardAbsorbed}.` : ''}`);
          if(e.behaviour==='leech'&&edmg>0&&e.hp>0){const healed=Math.max(1,Math.round(edmg*.25));e.hp=Math.min(e.maxHp,e.hp+healed);log.push(`🩸 The ${e.name} drinks the wound and restores ${healed} HP.`);}
          const reflectedRate = (p.abilities.includes('thorns') ? 0.25 : 0) + gearThornsRate(p);
          if (reflectedRate > 0 && edmg > 0 && e.hp > 0) {
            const reflected = Math.max(1, Math.round(edmg * Math.min(1.25, reflectedRate)));
            e.hp = Math.max(0, e.hp - reflected);
            log.push(`🌵 Thorns reflect ${reflected} damage back at the ${e.name}.${reflectedRate > 0.25 ? ' The armour bites deeper.' : ''}`);
          }
        }
      }
      const counterChance = (p.abilities.includes('counter') ? 0.15 + lb : 0) + weaponProcTotal(p, 'procCounterChance');
      if (counterChance > 0 && Math.random() < Math.min(0.95, counterChance) && e.hp > 0) {
        const cdmg = damageRoll(Math.max(1, Math.round(totalAtk(p) * 0.5)), e.def);
        e.hp = Math.max(0, e.hp - cdmg);
        log.push(`You riposte the ${e.name} for ${cdmg}.${weaponProcTotal(p, 'procCounterChance') > 0 ? ' The Impossible Arsenal answers the blow.' : ''}`);
      }
    }
  });
  return p;
}

// The first time a run's player would die, Second Wind (if learned) keeps
// them alive at 1 HP instead. Returns the (possibly revived) player and
// whether death was prevented.
function applySecondWind(player, log) {
  if (player.hp > 0) return { player, prevented: false };
  if (player.anomalySecondHeart && !player.usedAnomalySecondHeart) {
    const p = { ...player, hp: Math.max(1, Math.round(player.maxHp * 0.5)), usedAnomalySecondHeart: true };
    log.push('💗 The Second Heart detonates — death is refused. You return at 50% HP.');
    return { player: p, prevented: true };
  }
  if (player.abilities.includes('second_wind') && !player.usedSecondWind) {
    const p = { ...player, hp: 1, usedSecondWind: true };
    log.push('✦ The Phoenix Pact ignites — you cling to life with 1 HP instead of falling!');
    return { player: p, prevented: true };
  }
  return { player, prevented: false };
}

// Captures whatever weapon was equipped the moment a run actually ends
// (Second Wind failed to save them). Feeds Back with a Vengeance (Stamps 7)
// — the next run has a small chance to start already holding a Vorpal
// Sword built from this exact snapshot.
function snapshotDeathWeapon(weapon) {
  if (!weapon) return null;
  return { name: weapon.name, atk: weapon.atk || 0, def: weapon.def || 0, rarity: weapon.rarity || 'common' };
}

function grantLootForDefeated(player, enemies, log) {
  let p = player;
  enemies.forEach(e => {
    if (e.hp <= 0 && !e.lootGranted) {
      e.lootGranted = true;
      log.push(`The ${e.name} falls!`);
      if(e.behaviour==='volatile'){
        const blast=Math.max(1,Math.round(p.maxHp*.06));
        p={...p,hp:Math.max(0,p.hp-blast)};
        log.push(`💥 The ${e.name} detonates for ${blast} damage as it dies.`);
      }

      const kills = { ...(p.kills || {}) };
      const prevKills = kills[e.baseId] || 0;
      kills[e.baseId] = prevKills + 1;
      p = { ...p, kills };
      const eBiome = currentBiome(e.depth||1);
      p=recordBiomeMemory(p,eBiome,'kill',{depth:e.depth,name:e.name});
      if(e.champion){p=recordBiomeMemory(p,eBiome,'champion',e.name);log.push(`♛ ${e.name} enters the regional folklore by leaving it.`);}
      p=advanceContractsForKill(p,e,log);
      const soulHunterRare = p.soulHunterRareChance || 0;
      const soulHunterEnemy = p.soulHunterEnemyChance || 0;
      if ((e.rarity === 'rare' || e.rarity === 'legendary') && soulHunterRare > 0 && Math.random() * 100 < soulHunterRare) {
        p = { ...p, soulHunterRunSouls: (p.soulHunterRunSouls || 0) + 1 };
        log.push('👻 Soul Hunter! The fallen creature leaves behind a Soul.');
      } else if (soulHunterEnemy > 0 && Math.random() * 100 < soulHunterEnemy) {
        p = { ...p, soulHunterRunSouls: (p.soulHunterRunSouls || 0) + 1 };
        log.push('👻 Soul Hunter! A dying spark becomes a Soul.');
      }
      const leechChance = gearSoulLeechChance(p);
      if (leechChance > 0 && Math.random() * 100 < leechChance) {
        p = { ...p, soulHunterRunSouls: (p.soulHunterRunSouls || 0) + 1 };
        log.push('🩸 Leech gear drinks the final breath and condenses it into a Soul.');
      }
      const petSoulChance = activePetEffect(p, 'soulChance');
      if (petSoulChance > 0 && Math.random() * 100 < petSoulChance) {
        const pet = activePetOf(p);
        p = { ...p, soulHunterRunSouls: (p.soulHunterRunSouls || 0) + 1 };
        log.push(`🐾 ${pet?.name || 'Your companion'} sniffs a Soul out of the remains.`);
      }
      if (p.graduationUnlocked) {
        const skillPointChance = (e.rarity === 'rare' || e.rarity === 'legendary') ? 5 : 1;
        if (Math.random() * 100 < skillPointChance) {
          p = { ...p, bonusSkillPoints: (p.bonusSkillPoints || 0) + 1 };
          log.push(`🎓 Graduation: the ${e.name} drops an extra Skill Point!`);
        }
      }
      if (p.bossDividendUnlocked && (e.rarity === 'rare' || e.rarity === 'legendary') && Math.random() < .05) {
        p = { ...p, chests:(p.chests || 0) + 1 };
        log.push(`💰 BOSS DIVIDEND! The ${e.name} leaves one persistent Chest among the remains.`);
      }
      if (p.bestiaryUnlocked) {
        const milestoneThresholds = p.cards5Unlocked ? BESTIARY_THRESHOLDS_EXTENDED3
          : p.cards3Unlocked ? BESTIARY_THRESHOLDS_EXTENDED2
          : p.cards2Unlocked ? BESTIARY_THRESHOLDS_EXTENDED : BESTIARY_THRESHOLDS_BASE;
        milestoneThresholds.forEach(threshold => {
          if (prevKills + 1 === threshold) {
            log.push(`📖 Bestiary milestone: ${threshold} kills on the ${e.name}! Combat bonus against them increased.`);
          }
        });
      }

      const loot = rollLoot(e, p);
      const impossibleDrop = loot.items.find(item => item.proceduralWeapon);
      if (impossibleDrop) {
        p = recordImpossibleDiscovery(p, impossibleDrop, e.depth, `${e.rarity === 'legendary' ? 'Legendary' : e.rarity === 'rare' ? 'Rare' : 'Common'} enemy`);
        log.push(`💥 BAZINGA! The Impossible Arsenal opens: ${impossibleDrop.name} obeys ${impossibleDrop.procLawName}.`);
      }

      const killHealRate = Math.min(0.5, weaponProcTotal(p, 'procKillHealRate'));
      if (killHealRate > 0 && p.hp < p.maxHp) {
        const healed = Math.min(p.maxHp - p.hp, Math.max(1, Math.round(p.maxHp * killHealRate)));
        p = { ...p, hp: p.hp + healed };
        log.push(`🔥 ${healed} HP returns under the Law of Warm Ashes.`);
      }
      const petHealRate = activePetEffect(p, 'killHealRate');
      if (petHealRate > 0 && p.hp < p.maxHp) {
        const healed = Math.min(p.maxHp - p.hp, Math.max(1, Math.round(p.maxHp * petHealRate)));
        const pet = activePetOf(p);
        p = { ...p, hp:p.hp + healed };
        log.push(`❤️ ${pet?.name || 'Your companion'} tends your wounds for ${healed} HP.`);
      }
      const factionHealRate=factionPactEffect(p,currentBiome(e.depth||1),'killHealRate');
      if(factionHealRate>0&&p.hp>0&&p.hp<p.maxHp){const healed=Math.min(p.maxHp-p.hp,Math.max(1,Math.round(p.maxHp*factionHealRate)));p={...p,hp:p.hp+healed};log.push(`⚑ Your local faction pact restores ${healed} HP.`);}
      const phenomenonHeal=biomePhenomenon(eBiome).killHeal||0;
      if(phenomenonHeal>0&&p.hp>0&&p.hp<p.maxHp){const healed=Math.min(p.maxHp-p.hp,Math.max(1,Math.round(p.maxHp*phenomenonHeal)));p={...p,hp:p.hp+healed};log.push(`${biomePhenomenon(eBiome).icon} ${biomePhenomenon(eBiome).name} closes ${healed} HP of your wounds.`);}

      let goldGain = loot.gold;
      if (p.keyItems.includes('thief_signet')) goldGain = Math.round(goldGain * 1.15);
      if (p.relicGoldBonus) goldGain = Math.round(goldGain * (1 + p.relicGoldBonus));
      if (p.wealthLootBonus) goldGain = Math.round(goldGain * (1 + p.wealthLootBonus));
      const regionalGoldPct = ((p.regionalGoldBonus && p.regionalGoldBonus[eBiome]) || 0) / 100;
      const regionalLuckPct = ((p.regionalLuckBonus && p.regionalLuckBonus[eBiome]) || 0) / 100;
      if (regionalGoldPct) goldGain = Math.round(goldGain * (1 + regionalGoldPct));
      if (p.curiosGoldBonus) goldGain = Math.round(goldGain * (1 + p.curiosGoldBonus));
      if (p.doohickeyGoldRate) goldGain = Math.round(goldGain * (1 + p.doohickeyGoldRate));
      if (p.ascensionGoldMult) goldGain = Math.round(goldGain * (1 + p.ascensionGoldMult));
      const impossibleGoldBonus = Math.min(2, weaponProcTotal(p, 'procGoldBonus'));
      if (impossibleGoldBonus) goldGain = Math.round(goldGain * (1 + impossibleGoldBonus));
      const petGoldRate = activePetEffect(p, 'goldRate');
      if (petGoldRate) goldGain = Math.round(goldGain * (1 + petGoldRate));
      const factionGoldRate=factionPactEffect(p,eBiome,'goldRate');
      if(factionGoldRate)goldGain=Math.round(goldGain*(1+factionGoldRate));
      const memoryProfile=memoryCombatProfile(p,eBiome);
      if(memoryProfile.goldRate)goldGain=Math.round(goldGain*(1+memoryProfile.goldRate));
      p = { ...p, gold: p.gold + goldGain };

      let xpGain = e.xp;
      if (p.keyItems.includes('sage_monocle')) xpGain = Math.round(xpGain * 1.15);
      if (p.relicXpBonus) xpGain = Math.round(xpGain * (1 + p.relicXpBonus));
      if (p.ascensionXpMult) xpGain = Math.round(xpGain * (1 + p.ascensionXpMult));
      const impossibleXpBonus = Math.min(2, weaponProcTotal(p, 'procXpBonus'));
      if (impossibleXpBonus) xpGain = Math.round(xpGain * (1 + impossibleXpBonus));
      const petXpRate = activePetEffect(p, 'xpRate');
      if (petXpRate) xpGain = Math.round(xpGain * (1 + petXpRate));
      const factionXpRate=factionPactEffect(p,eBiome,'xpRate');
      if(factionXpRate)xpGain=Math.round(xpGain*(1+factionXpRate));
      if(memoryProfile.xpRate)xpGain=Math.round(xpGain*(1+memoryProfile.xpRate));
      const { player: leveledPlayer, leveled } = applyXp(p, xpGain);
      p = leveledPlayer;

      if (loot.potions) p = { ...p, potions: p.potions + loot.potions };
      if (loot.greaterPotions) p = { ...p, greaterPotions: p.greaterPotions + loot.greaterPotions };
      const petPotionChance = activePetEffect(p, 'potionChance');
      if (petPotionChance > 0 && Math.random() * 100 < petPotionChance) {
        const pet = activePetOf(p);
        p = { ...p, potions:p.potions + 1 };
        log.push(`🧪 ${pet?.name || 'Your companion'} forages a Health Potion from somewhere best left unexplained.`);
      }
      loot.items.forEach(it => {
        p = stashInventoryItem(p, it);
      });

      if (loot.throwables) {
        p = { ...p, throwablesBag: [...(p.throwablesBag || []), { ...THROWABLES[0], uid: uid('knives'), count: loot.throwables }] };
      }
      if (loot.bullets) p = { ...p, bullets: (p.bullets || 0) + loot.bullets };
      if (loot.arrows) p = { ...p, arrows: (p.arrows || 0) + loot.arrows };

      // Madgod procs on kill loot
      const madgod = p.madgodChance || 0;
      if (madgod > 0) {
        if (loot.items.length > 0 && Math.random() * 100 < madgod) {
          const duped = { ...pickRandom(loot.items), uid: uid('duped') };
          p = stashInventoryItem(p, duped);
          log.push(`✨ The Madgod cackles — you find a duplicate ${duped.name}!`);
        }
        if (Math.random() * 100 < madgod) {
          p = { ...p, elixirsOfLife: (p.elixirsOfLife || 0) + 1 };
          log.push('✨ The Madgod blesses you — an Elixir of Life materialises in your hands!');
        }
      }

      if (loot.chest) {
        p = { ...p, chests: (p.chests || 0) + 1 };
        log.push('🧰 You find a sealed Chest among the remains. It stays in your pack until opened or this run ends.');
      }

      if (loot.keyItem) {
        const ki = relicById(loot.keyItem);
        if (ki) {
          p = applyRelicEffect(p, ki);
          p = { ...p, keyItems: [...p.keyItems, ki.id] };
          const curseTag = ki.cursed ? ' ☠️ CURSED' : '';
          log.push(`✨ Relic found: ${ki.name}${curseTag}! ${ki.desc}`);
        }
      }

      let lootMsg = `Loot: +${goldGain}g, +${xpGain}xp`;
      if (loot.items.length) lootMsg += `, found ${loot.items.map(i => i.name).join(', ')}`;
      if (loot.potions) lootMsg += `, +${loot.potions} potion`;
      if (loot.greaterPotions) lootMsg += `, +${loot.greaterPotions} elixir`;
      if (loot.throwables) lootMsg += `, +${loot.throwables} Throwing Knives`;
      if (loot.bullets) lootMsg += `, +${loot.bullets} Bullets`;
      if (loot.arrows) lootMsg += `, +${loot.arrows} Arrows`;
      log.push(lootMsg);
      if (loot.paginationProc) log.push('📖 Double Pagination — the tome copies itself in your hands!');
      if (leveled) log.push(`✦ You reached level ${p.level}! HP and stats increased, wounds mended.`);

      const collChance = (e.rarity === 'common' ? 0.12 : 0.3) + luckBonus(p) + regionalLuckPct;
      if (Math.random() < collChance) {
        const coll = rollCollectible(p);
        if (coll) {
          const updatedList = [...p.collectibles[coll.category], coll.index];
          p = {
            ...p,
            collectibles: { ...p.collectibles, [coll.category]: updatedList },
            collectibleOrigins: { ...(p.collectibleOrigins || {}), [`${coll.category}:${coll.index}`]: currentBiome(e.depth) },
            pendingNames: [...p.pendingNames, { category: coll.category, index: coll.index }],
          };
          const meta = COLLECTIBLE_META[coll.category];
          const singular = meta.label.slice(0, -1).toLowerCase();
          log.push(`${meta.icon} You find a curious ${singular} — added to your collection! (${meta.label} ${updatedList.length}/50)`);
        }
      }
      if (Object.keys(SUBCOLLECTIBLE_META).some(k => SUBCOLLECTIBLE_META[k].unlock(p)) && Math.random() < 0.05) {
        p = applySubcollectibleFind(p, log, null, e.depth);
      }
    }
  });
  return p;
}

const DOOHICKEY_CABINET_COST = 250;
const DOOHICKEY_CATEGORY_KEYS = ['emberbeans','snowpeas','sparkpups','bogbuns','sunmotes','shadowmews','runelings','puddlepals','bravebuttons','shieldtots','heartkins','sipsprites','bondbugs','coinkittens','bookbunnies'];

function freshDoohickeyBonuses() {
  return Object.fromEntries(DOOHICKEY_CATEGORY_KEYS.map(key => [key, 0]));
}

function freshSubcollectibles() {
  return Object.fromEntries(['statues','sigils','curios','gemstones','reliquaries',...DOOHICKEY_CATEGORY_KEYS].map(key => [key, []]));
}

function doohickeyCabinetUnlocked(holder) {
  return !!holder?.doohickeyCabinetsUnlocked;
}

