  sunmotes:['Sunmote','Dawnling','Halo Hamster','Glimmerpip'], shadowmews:['Shadowmew','Gloam Kitten','Nightbean','Whispercat'],
  runelings:['Runeling','Spellmoth','Glyphlet','Hex Hamster'], puddlepals:['Puddlepal','Droplet','Tide Tadpole','Bubblebun'],
  bravebuttons:['Brave Button','Swordbean','Courage Pip','Tiny Champion'], shieldtots:['Shieldtot','Guardbun','Tin Turtle','Wall Peep'],
  heartkins:['Heartkin','Pulse Puff','Cuddle Valve','Lovebug'], sipsprites:['Sip Sprite','Potion Peep','Corkling','Tonic Tadpole'],
